.brands-story-copy{max-width:610px}
.brands-story .kicker{color:#a97e60;margin-bottom:24px}
.brands-story h2{font-family:Georgia,"Times New Roman",serif;font-size:clamp(48px,5vw,76px);font-weight:400;letter-spacing:-.035em;line-height:1.06;margin:0 0 22px}
.brands-story p:not(.kicker){font-size:18px;line-height:1.6;color:#eee9e5;margin:0 0 24px}
.brands-discover{display:inline-flex;align-items:center;justify-content:center;width:max-content;padding:10px 17px!important;border:1px solid rgba(255,255,255,.78)!important;border-radius:999px;background:rgba(255,255,255,.03);color:#fff;line-height:1!important;font-weight:600;cursor:pointer;transition:background .2s,color .2s,border-color .2s,transform .2s}
.brands-discover:hover,.brands-discover:focus-visible{background:#fff;color:#29221e;border-color:#fff!important;transform:translateY(-1px);outline:none}
.brands-story-image{width:100%;height:410px;object-fit:cover}
.brands-carousel-bar{display:flex;align-items:end;justify-content:space-between;gap:30px;margin-bottom:20px}
.brands-carousel-label{color:#a97e60;margin:0}
.brands-carousel-label:before{background:#a97e60}
.brands-carousel-actions{display:flex;gap:12px}
.brands-carousel-actions button{position:relative;width:54px;height:54px;padding:0;border-radius:50%;border:1px solid rgba(255,255,255,.28);background:transparent;color:#fff;font-size:0;line-height:0;cursor:pointer;transition:background .2s,border-color .2s,transform .2s}
.brands-carousel-actions button svg{position:absolute;top:50%;display:block;width:18px;height:18px;transform:translate(-50%,-50%);fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
.brands-carousel-actions button[data-brand-prev] svg{left:calc(50% + .5px)}
.brands-carousel-actions button[data-brand-next] svg{left:calc(50% - .5px)}
.brands-carousel-actions button:hover,.brands-carousel-actions button:focus-visible{background:#fff;color:#171717;border-color:#fff;transform:translateY(-2px);outline:none}
.brands-carousel-window{overflow:hidden;background:#f8f7f5}
.brands-carousel-track{display:flex;overflow-x:auto;scroll-behavior:smooth;scroll-snap-type:x mandatory;scrollbar-width:none}
.brands-carousel-track::-webkit-scrollbar{display:none}
.brand-logo-card{background:#f8f7f5;border-color:#dedbd7}
.brand-logo-card:hover,.brand-logo-card:focus-visible,.brand-logo-card.selected{background:#fff}
@media(max-width:900px){.brands-story{grid-template-columns:1fr;gap:36px}.brands-story-image{height:360px}.brands-carousel-bar{align-items:center}}
@media(max-width:560px){.brands-carousel{padding:58px 20px 68px}.brands-story{margin-bottom:38px}.brands-story h2{font-size:45px}.brands-story p:not(.kicker){font-size:16px}.brands-story-image{height:270px}.brands-carousel-actions button{width:46px;height:46px}}

/* Brand showcase spacing and warm logo surface refinement */
.brands-story{margin-bottom:24px;align-items:center}
.brands-story-image{height:340px;max-width:880px;justify-self:end}
.brands-story-copy>p:not(.kicker){margin-bottom:0}
.brands-discover{margin-top:34px}
.brands-carousel-bar{justify-content:flex-end;margin-bottom:12px;min-height:54px}
.brands-carousel-label{display:none}
.brands-carousel-window{background:#d8cfc8}
.brand-logo-card{height:154px;background:#d8cfc8;border-color:#bfb3aa}
.brand-logo-card:hover,.brand-logo-card:focus-visible,.brand-logo-card.selected{background:#e8e0da}
@media(max-width:900px){.brands-story{margin-bottom:20px}.brands-story-image{height:320px;max-width:none}.brands-carousel-bar{margin-top:0}}
@media(max-width:560px){.brands-story-image{height:245px}.brands-discover{margin-top:26px}.brands-carousel-bar{min-height:46px;margin-bottom:10px}.brand-logo-card{height:122px}}

/* Align brand controls with the discovery link */
.brands-story{position:relative;align-items:start;margin-bottom:16px}
.brands-story-image{height:280px}
.brands-carousel-bar{position:absolute;right:0;bottom:0;margin:0;min-height:0;z-index:2}
@media(max-width:900px){.brands-story{margin-bottom:12px}.brands-story-image{height:300px}.brands-carousel-bar{position:static;grid-column:1/-1;justify-content:flex-end;margin:-2px 0 0}}
@media(max-width:560px){.brands-story-image{height:230px}.brands-carousel-bar{margin-top:2px}}

/* Prevent brand controls overlap and soften showroom transition */
@media(min-width:901px){
  .brands-story-image{height:230px;width:94%;object-position:center}
  .brands-carousel-bar{bottom:0}
}
.showroom{padding-top:88px;padding-bottom:0}
@media(max-width:900px){.showroom{padding-top:68px}}
@media(max-width:560px){.showroom{padding-top:48px}}

/* Crisp, separated Likya Yapı vector logo */
.logo{width:100px;height:64px;display:flex;align-items:center}
.logo img{width:100%;height:auto}
.footer-logo{display:inline-block;width:108px}
.footer-logo img{width:100%;height:auto}
@media(max-width:850px){.logo{width:68px;height:52px}}
@media(max-width:560px){.logo{width:62px;height:48px}.footer-logo{width:96px}}

/* Exact supplied Likya Yapı logo artwork */
.logo{width:96px;height:72px}
.logo img{width:100%;height:auto;object-fit:contain}
.footer-logo{width:104px}
.footer-logo img{width:100%;height:auto;object-fit:contain}
@media(max-width:850px){.logo{width:66px;height:56px}}
@media(max-width:560px){.logo{width:60px;height:52px}.footer-logo{width:94px}}

/* Architects and professionals page */
.header nav{gap:clamp(13px,1.75vw,30px)}
.header nav a{white-space:nowrap}
.pro-intro{background:#e9e0da}
.pro-intro img{width:100%;height:440px;object-fit:cover}
.pro-services{background:#1a1a19;color:#eee9e5}
.pro-services>.kicker{color:#b58a69}
.pro-services .section-head{align-items:start;gap:60px}
.pro-services .section-head h2{max-width:650px}
.pro-services .section-head p{max-width:420px;margin:0;color:#bbb4ae}
.pro-service-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#4b4540;margin-top:48px}
.pro-service-grid article{background:#1a1a19;padding:42px 36px;min-height:285px}
.pro-service-grid span{font:24px Georgia,serif;color:#b58a69}
.pro-service-grid h3{font-size:27px;line-height:1.18;margin:36px 0 17px}
.pro-service-grid p{color:#bdb6b0;font-size:14px}
.pro-process{display:grid;grid-template-columns:.72fr 1.28fr;gap:8vw}
.pro-process-list article{display:grid;grid-template-columns:60px 1fr;gap:26px;padding:28px 0;border-top:1px solid var(--line)}
.pro-process-list b{font:24px Georgia,serif;color:#8e715d}
.pro-process-list h3{font-size:25px;margin-bottom:8px}
.pro-process-list p{margin:0;max-width:650px}
@media(max-width:1050px){.header nav{gap:12px}.header nav a{font-size:11px}}
@media(max-width:850px){.pro-service-grid{grid-template-columns:1fr}.pro-service-grid article{min-height:auto}.pro-process{grid-template-columns:1fr}.pro-intro img{height:360px}}
@media(max-width:560px){.header nav{justify-content:flex-start;overflow-x:auto;gap:20px;padding-inline:18px}.header nav::-webkit-scrollbar{display:none}.pro-services .section-head{display:block}.pro-services .section-head p{margin-top:22px}.pro-service-grid article{padding:34px 26px}.pro-process-list article{grid-template-columns:42px 1fr}.pro-intro img{height:270px}}

/* Professional technical product hub */
.pro-catalog{background:#e8dfd9}
.pro-catalog-head{display:grid;grid-template-columns:1fr .82fr;gap:8vw;align-items:end;margin-bottom:56px}
.pro-catalog-head>p{max-width:600px;margin:0;color:#5f5650}
.pro-catalog-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.pro-product-card{background:#f0e9e4;border:1px solid #cbbeb5}
.pro-product-image{display:block;overflow:hidden}
.pro-product-image img{width:100%;height:260px;object-fit:cover;transition:transform .45s ease}
.pro-product-card:hover .pro-product-image img{transform:scale(1.025)}
.pro-product-body{padding:27px 27px 30px}
.pro-product-category{font-size:10px;letter-spacing:.17em;text-transform:uppercase;color:#8a6e5a;margin:0 0 12px}
.pro-product-body h3{font-size:29px;line-height:1.08;min-height:62px}
.pro-product-body dl{margin:24px 0}
.pro-product-body dl>div{display:grid;grid-template-columns:76px 1fr;gap:12px;border-top:1px solid #cbbeb5;padding:10px 0;font-size:12px}
.pro-product-body dt{color:#786b63}.pro-product-body dd{margin:0}
.pro-detail-link{display:inline-block;border-bottom:1px solid;padding-bottom:5px;font-size:12px}
.pro-support{background:#1b1b1a;color:#eee9e5;display:grid;grid-template-columns:.55fr 1.45fr;gap:7vw}
.pro-support>.pro-support-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#4a4541}
.pro-support-grid article{background:#1b1b1a;padding:8px 28px 20px}
.pro-support-grid b{font:23px Georgia,serif;color:#b28a6c}
.pro-support-grid h3{font-size:25px;margin:28px 0 12px}.pro-support-grid p{color:#bdb5af;font-size:13px}
.pro-tech-detail{display:grid;grid-template-columns:1fr 1fr;gap:7vw;align-items:start}
.pro-tech-visual img{width:100%;height:660px;object-fit:cover}.pro-tech-visual>p{font-size:10px;color:#776d66}
.pro-tech-copy h2{font-size:clamp(42px,4.6vw,68px);margin-bottom:25px}.pro-tech-lead{font-size:16px;color:#5f5650}
.pro-spec-list{margin:36px 0}.pro-spec-list>div{display:grid;grid-template-columns:165px 1fr;gap:24px;padding:17px 0;border-top:1px solid var(--line)}
.pro-spec-list dt{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#806f64}.pro-spec-list dd{margin:0;font-size:14px;line-height:1.5}
.pro-tech-actions{display:flex;flex-direction:column;align-items:flex-start;gap:16px}.pro-tech-actions a{font-size:13px;border-bottom:1px solid;padding-bottom:6px}
.pro-tech-actions .pro-primary-action{background:#1b1b1a;color:#fff;border:0;padding:16px 20px}
@media(max-width:1050px){.pro-catalog-grid{grid-template-columns:repeat(2,1fr)}.pro-support{grid-template-columns:1fr}.pro-tech-visual img{height:520px}}
@media(max-width:700px){.pro-catalog-head,.pro-tech-detail{grid-template-columns:1fr}.pro-catalog-grid{grid-template-columns:1fr}.pro-support>.pro-support-grid{grid-template-columns:1fr}.pro-product-image img{height:230px}.pro-product-body h3{min-height:auto}.pro-tech-visual img{height:340px}.pro-spec-list>div{grid-template-columns:1fr;gap:7px}}

/* Technical information inside the original product detail layout */
.product-detail-enhanced{align-items:start}
.product-detail-enhanced>img{height:560px;object-fit:cover;object-position:center;order:-1}
.product-spec-heading{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-top:30px;padding-bottom:10px;border-bottom:1px solid var(--line)}
.product-spec-heading span{font-size:11px;letter-spacing:.14em;color:#806f64}
.product-spec-heading small{font-size:10px;color:#81766f}
.legacy-detail-specs{margin:0 0 25px}
.legacy-detail-specs>div{display:grid;grid-template-columns:135px 1fr;gap:18px;padding:12px 0;border-bottom:1px solid var(--line)}
.legacy-detail-specs dt{font-size:10px;letter-spacing:.07em;text-transform:uppercase;color:#806f64}
.legacy-detail-specs dd{margin:0;font-size:12px;line-height:1.45}
@media(max-width:850px){.product-detail-enhanced>img{height:380px}.legacy-detail-specs>div{grid-template-columns:120px 1fr}}
@media(max-width:560px){.product-detail-enhanced>img{height:260px}.product-spec-heading{display:block}.product-spec-heading small{display:block;margin-top:7px}.legacy-detail-specs>div{grid-template-columns:1fr;gap:5px}}
.product-gallery{position:relative;width:100%;min-width:0;order:-1;z-index:1}
.product-gallery-stage{position:relative;width:100%;height:560px;overflow:hidden;background:#d8cec7;cursor:zoom-in}
.product-gallery-stage>img{width:100%;height:100%;object-fit:cover;object-position:center}
.product-gallery-lens{position:absolute;width:34%;height:34%;border:1px solid rgba(47,39,34,.72);background:rgba(238,230,224,.38);pointer-events:none;opacity:0;z-index:3}
.product-gallery-zoom{position:absolute;left:calc(100% + 8vw);top:0;width:115%;height:560px;background-color:#e7ddd6;background-repeat:no-repeat;background-size:294% 294%;border:1px solid rgba(128,111,100,.25);box-shadow:0 18px 42px rgba(31,25,21,.16);pointer-events:none;opacity:0;visibility:hidden;z-index:40;transition:opacity .15s ease}
.product-gallery.is-zooming{z-index:50}.product-gallery.is-zooming .product-gallery-lens,.product-gallery.is-zooming .product-gallery-zoom{opacity:1;visibility:visible}
.product-gallery-nav{position:absolute;top:50%;width:44px;height:44px;border:1px solid rgba(42,35,30,.2);border-radius:50%;background:rgba(250,247,244,.92);color:#2b2521;display:grid;place-items:center;cursor:pointer;transform:translateY(-50%);z-index:5;box-shadow:0 5px 16px rgba(24,20,17,.12);transition:background .2s,transform .2s}
.product-gallery-nav:hover,.product-gallery-nav:focus-visible{background:#fff;transform:translateY(-50%) scale(1.05);outline:none}.product-gallery-nav svg{width:18px;height:18px}.product-gallery-prev{left:16px}.product-gallery-next{right:16px}
.product-gallery-thumbs{display:flex;gap:10px;margin-top:12px;overflow-x:auto;scrollbar-width:none}
.product-gallery-thumbs::-webkit-scrollbar{display:none}
.product-gallery-thumb{flex:0 0 78px;width:78px;height:60px;padding:3px;border:1px solid rgba(128,111,100,.34);background:transparent;cursor:pointer;transition:border-color .2s,background .2s}
.product-gallery-thumb img{width:100%;height:100%;object-fit:cover;pointer-events:none}
.product-gallery-thumb.active,.product-gallery-thumb:hover,.product-gallery-thumb:focus-visible{border-color:#80634f;background:rgba(128,99,79,.08);outline:none}
@media(max-width:850px){.product-gallery-stage{height:380px;cursor:default}.product-gallery-lens,.product-gallery-zoom{display:none}.product-gallery-nav{width:40px;height:40px}}
@media(max-width:560px){.product-gallery-stage{height:260px}.product-gallery-nav{width:36px;height:36px}.product-gallery-prev{left:10px}.product-gallery-next{right:10px}.product-gallery-thumb{flex-basis:66px;width:66px;height:52px}}
.contact-form-area{align-self:start}.contact-form-tabs{display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid var(--line);margin-bottom:30px}.contact-form-tabs button{border:0;background:transparent;color:#75675e;padding:15px 10px;text-align:left;cursor:pointer;border-bottom:2px solid transparent}.contact-form-tabs button.selected{color:var(--ink);border-color:var(--ink)}.contact-form-tabs button span{display:block;font-family:Georgia,"Times New Roman",serif;font-size:20px;margin-bottom:5px}.contact-form-tabs button small{font-size:10px;line-height:1.4}.contact-choice-panel{display:none}.contact-choice-panel.active{display:grid}.contact select{width:100%;border:0;border-bottom:1px solid var(--line);background:transparent;padding:7px 4px 5px;outline:none;color:var(--ink)}.professional-form .form-grid{display:grid;grid-template-columns:1fr 1fr;column-gap:22px;row-gap:24px}.professional-form .form-grid .full{grid-column:1/-1}.form-panel-intro{font-size:13px;color:#66594f;margin:0 0 8px}@media(max-width:560px){.contact>div{padding:24px 20px 28px}.contact-form-tabs{grid-template-columns:1fr}.professional-form .form-grid{grid-template-columns:1fr}.professional-form .form-grid .full{grid-column:auto}}
.about-process>.lead{max-width:780px;margin:22px 0 0;color:#5f524a}.about-process .steps{margin-bottom:0}.about-process .steps h3{font-size:24px;margin:5px 0 12px}.about-process .steps p{max-width:390px;margin:0;color:#665950;font-size:14px;line-height:1.65}
.brands-page-intro{display:grid;grid-template-columns:1.15fr .85fr;gap:80px;align-items:end}.brands-page-intro .lead{margin:0;max-width:590px}.brand-page-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr))!important;margin-top:55px;border-top:1px solid var(--line);border-left:1px solid var(--line)}.brand-page-card{--brand-color:#222;display:block;min-width:0;min-height:150px;border:0;border-right:1px solid var(--line);border-bottom:1px solid var(--line);background:#d9cec7;color:#a79f9a;cursor:pointer;padding:20px;transition:background .25s,color .25s,transform .25s}.brand-page-card:hover,.brand-page-card:focus-visible,.brand-page-card.selected{color:var(--brand-color);background:#eee7e1;outline:none}.brand-page-card:hover{transform:translateY(-3px)}.brand-page-card .brand-logo{display:flex;min-height:108px;align-items:center;justify-content:center}.brand-page-card .brand-logo>strong,.brand-page-card .brand-logo>span{transform:scale(.84)}.brand-page-card:hover .brand-logo,.brand-page-card:focus-visible .brand-logo,.brand-page-card.selected .brand-logo{color:var(--brand-color);filter:grayscale(0);opacity:1;transform:scale(1.035)}.brand-page-card:focus-visible{box-shadow:inset 0 0 0 2px var(--brand-color)}.brand-detail{display:grid;grid-template-columns:.75fr 1.25fr;gap:70px;background:#181818;color:#f4eee9;padding:60px 7%;align-items:center}.brand-detail h2{font-size:clamp(42px,5vw,76px);margin:8px 0}.brand-detail .kicker{color:#bc805d}.brand-detail p{font-size:18px;line-height:1.7;color:#cfc6bf;max-width:760px}.brand-detail a{display:inline-block;margin-top:18px;color:#fff;border-bottom:1px solid #777;padding-bottom:8px}.brand-page-note{font-size:13px;color:#76685f;margin-top:18px}@media(max-width:900px){.brands-page-intro,.brand-detail{grid-template-columns:1fr;gap:25px}.brand-page-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important}}@media(max-width:560px){.brand-page-grid{grid-template-columns:1fr!important}.brand-page-card{min-height:135px}.header nav{gap:5px}.header nav a{font-size:8px}}

/* Unified site typography system */
:root{
  --font-site:"Poppins",Arial,sans-serif;
  --type-body:16px;
  --type-small:13px;
  --type-label:11px;
  --leading-body:1.6;
  --tracking-heading:-.025em;
}
body,button,input,textarea,select{font-family:var(--font-site);font-style:normal}
body{font-size:var(--type-body);line-height:var(--leading-body)}
h1,h2,h3,h4,h5,h6,.footer-logo{font-family:var(--font-site)!important;font-style:normal!important;color:inherit}
h1{font-size:clamp(46px,5.4vw,76px)!important;line-height:1.04!important;letter-spacing:-.035em!important;font-weight:500!important}
h2{font-size:clamp(32px,3.9vw,56px)!important;line-height:1.1!important;letter-spacing:var(--tracking-heading)!important;font-weight:500!important}
h3{font-size:clamp(20px,2vw,28px)!important;line-height:1.2!important;letter-spacing:-.015em!important;font-weight:500!important}
h4,h5,h6{line-height:1.3!important;letter-spacing:0!important;font-weight:600!important}
p,.lead{font-size:var(--type-body);line-height:var(--leading-body);letter-spacing:0}
.hero-copy p{margin-top:20px;max-width:650px}
.kicker{font-family:var(--font-site);font-size:var(--type-label)!important;line-height:1.4;letter-spacing:.16em!important;font-weight:600;text-transform:uppercase}
.header nav a,.lang{font-family:var(--font-site);font-size:13px!important;line-height:1.2;letter-spacing:.01em;font-weight:500}
.section-head>a,.split a,.hero-link,.brands-discover,.project-grid span,.reference-grid span,.cta a,.brand-detail a{font-family:var(--font-site);font-size:var(--type-small)!important;line-height:1.35;letter-spacing:.01em;font-weight:600}
.filters button,.contact-tabs button,.contact button,.contact-form button{font-family:var(--font-site);font-size:var(--type-small)!important;line-height:1.35;letter-spacing:.01em;font-weight:600}
.footer,.footer a,.footer p,.footer h4,.legal{font-family:var(--font-site);line-height:1.55;letter-spacing:0}
.footer{font-size:12px}.footer h4{font-size:var(--type-label)!important;letter-spacing:.1em!important;font-weight:600}
.contact label,.product-specs dt,.product-specs dd,.technical-table,.brand-page-note{font-family:var(--font-site);letter-spacing:0;line-height:1.5}
.steps b,.three b{font-family:var(--font-site)!important;font-weight:500;letter-spacing:-.02em}
@media(max-width:850px){h1{font-size:clamp(42px,8vw,64px)!important}h2{font-size:clamp(30px,6vw,48px)!important}.header nav a,.lang{font-size:11px!important}}
@media(max-width:560px){h1{font-size:42px!important;line-height:1.06!important}h2{font-size:34px!important}.header nav a,.lang{font-size:10px!important}p,.lead{font-size:15px}}
/* Home hero link spacing */
.hero-copy .hero-link{display:inline-block;margin-top:0;position:relative;top:18px}
@media(max-width:560px){.hero-copy .hero-link{margin-top:0;top:14px}}
/* Separate brand arrows from showroom image */
@media(min-width:901px){
  .brands-carousel-bar{bottom:-12px}
}
/* Balance space around brand arrows */
@media(min-width:901px){
  .brands-carousel-window{margin-top:18px}
}
/* Enforce visible clearance below brand arrows */
@media(min-width:901px){
  .brands-carousel-window{margin-top:0;border-top:32px solid #171717}
}
/* Lower brand discovery and arrows together */
@media(min-width:901px){
  .brands-discover{position:relative;top:12px}
  .brands-carousel-bar{transform:translateY(12px)}
}
/* Product detail category badge */
.product-detail-enhanced>div>.kicker,
.product-index-section>.kicker,
.catalog-section>.kicker,
.references-index-section>.kicker,
.detail-section:not(.product-detail-enhanced)>div>.kicker{
  display:inline-flex;
  align-items:center;
  width:max-content;
  margin:0 0 18px;
  padding:8px 14px;
  border:1px solid #c5b5aa;
  border-radius:999px;
  background:#d8cfc8;
  color:#5f4c40;
  font-size:10px!important;
  line-height:1;
  letter-spacing:.12em!important;
  font-weight:600;
}
@media(max-width:560px){.product-detail-enhanced>div>.kicker,.product-index-section>.kicker,.catalog-section>.kicker,.references-index-section>.kicker,.detail-section:not(.product-detail-enhanced)>div>.kicker{padding:7px 12px;margin-bottom:16px}}
/* Product detail action buttons */
.product-detail-enhanced .detail-actions{display:flex;align-items:center;gap:12px;margin-top:26px}
.product-detail-enhanced .detail-actions a{
  min-height:46px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  padding:12px 20px;
  border:1px solid #1b1b1a;
  border-radius:3px;
  border-bottom:1px solid #1b1b1a!important;
  font-size:12px!important;
  font-weight:600;
  line-height:1.2;
  transition:background .2s,color .2s,border-color .2s,transform .2s;
}
.product-detail-enhanced .detail-actions a:first-child{background:#1b1b1a;color:#fff}
.product-detail-enhanced .detail-actions a:first-child:hover{background:#8b6b55;border-color:#8b6b55;transform:translateY(-2px)}
.product-detail-enhanced .detail-actions a:last-child{background:transparent;color:#1b1b1a}
.product-detail-enhanced .detail-actions a:last-child:hover{background:#1b1b1a;color:#fff;transform:translateY(-2px)}
@media(max-width:560px){.product-detail-enhanced .detail-actions{align-items:stretch}.product-detail-enhanced .detail-actions a{flex:1 1 100%;width:100%}}

/* Reference detail action buttons */
.detail-section:not(.product-detail-enhanced) .detail-actions{display:flex;align-items:center;gap:14px;margin-top:28px}
.detail-section:not(.product-detail-enhanced) .detail-actions a{min-height:46px;display:inline-flex;align-items:center;justify-content:center;padding:12px 20px;border:1px solid #1b1b1a;border-radius:3px;border-bottom:1px solid #1b1b1a!important;font-size:12px!important;font-weight:600;line-height:1.2;transition:background .2s,color .2s,border-color .2s,transform .2s}
.detail-section:not(.product-detail-enhanced) .detail-actions a:first-child{background:#1b1b1a;color:#fff;font-size:0!important}
.detail-section:not(.product-detail-enhanced) .detail-actions a:first-child::before{content:"Benzer Bir Proje İçin Görüşün";font-size:12px}
.detail-section:not(.product-detail-enhanced) .detail-actions a:first-child:hover{background:#8b6b55;border-color:#8b6b55;transform:translateY(-2px)}
.detail-section:not(.product-detail-enhanced) .detail-actions a:last-child{background:transparent;color:#1b1b1a}
.detail-section:not(.product-detail-enhanced) .detail-actions a:last-child:hover{background:#1b1b1a;color:#fff;transform:translateY(-2px)}
@media(max-width:560px){.detail-section:not(.product-detail-enhanced) .detail-actions{align-items:stretch}.detail-section:not(.product-detail-enhanced) .detail-actions a{flex:1 1 100%;width:100%}}

.catalog-section{padding-top:72px}.catalog-breadcrumb{display:flex;align-items:center;gap:10px;margin-bottom:42px;font-size:12px;color:#8a7566}.catalog-breadcrumb a{border-bottom:1px solid transparent}.catalog-breadcrumb a:hover{border-color:currentColor}.catalog-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:42px}.catalog-grid .catalog-card{min-height:360px;background-size:cover;background-position:center;display:flex;align-items:flex-end;color:#fff;padding:26px;transition:transform .25s ease,filter .25s ease}.catalog-grid .catalog-card:hover{transform:translateY(-4px);filter:brightness(1.06)}.catalog-grid .catalog-card h3{font-size:30px;margin:0 0 8px}.catalog-grid .catalog-card span{font-size:12px;font-weight:600}.product-detail-enhanced .kicker:has(+h2){max-width:max-content}@media(max-width:900px){.catalog-grid{grid-template-columns:1fr 1fr}}@media(max-width:560px){.catalog-section{padding-top:50px}.catalog-grid{grid-template-columns:1fr}.catalog-grid .catalog-card{min-height:300px}.catalog-breadcrumb{flex-wrap:wrap;margin-bottom:30px}}
/* Ürün detaylarında aynı marka ve kategoriden benzer ürünler */
.related-products{background:#e7ddd6;padding-top:58px;padding-bottom:68px;border-top:1px solid rgba(128,111,100,.24)}
.related-products-head{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:25px}
.related-products-head>div{max-width:760px}
.related-products-head .kicker{margin:0 0 10px}
.related-products-head h2{font-size:clamp(28px,2.7vw,42px)!important}
.related-products-actions{display:flex;gap:9px;flex:0 0 auto}
.related-products-actions button{width:42px;height:42px;display:grid;place-items:center;border:1px solid rgba(71,57,48,.48);border-radius:50%;background:transparent;color:#29221e;cursor:pointer;transition:background .2s,color .2s,border-color .2s}
.related-products-actions button:hover,.related-products-actions button:focus-visible{background:#29221e;border-color:#29221e;color:#fff;outline:none}
.related-products-actions svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.related-products-grid{display:flex;gap:12px;overflow-x:auto;scroll-behavior:smooth;scroll-snap-type:x mandatory;scrollbar-width:none}
.related-products-grid::-webkit-scrollbar{display:none}
.related-product-card{min-width:0;flex:0 0 calc((100% - 36px)/4);display:grid;grid-template-columns:138px minmax(0,1fr) auto;align-items:center;gap:18px;min-height:138px;padding:12px 15px 12px 12px;background:rgba(255,255,255,.16);border:1px solid rgba(128,111,100,.3);color:#29221e;scroll-snap-align:start;transition:background .2s,border-color .2s,transform .2s}
.related-product-card:hover,.related-product-card:focus-visible{background:rgba(255,255,255,.38);border-color:rgba(88,69,57,.52);transform:translateY(-2px);outline:none}
.related-product-thumb{display:block;width:138px;height:112px;background-position:center;background-size:cover}
.related-product-card-copy{min-width:0}
.related-product-card small{display:block;margin-bottom:7px;color:#806f64;font-size:9px;font-weight:600;letter-spacing:.12em;text-transform:uppercase}
.related-product-card h3{font-size:clamp(17px,1.25vw,21px)!important;margin:0;overflow-wrap:anywhere}
.related-product-card>b{display:inline-flex;align-items:center;justify-content:center;padding:7px 12px;border:1px solid rgba(71,57,48,.58);border-radius:999px;font-size:9px;font-weight:600;white-space:nowrap;transition:background .2s,color .2s}
.related-product-card:hover>b,.related-product-card:focus-visible>b{background:#29221e;color:#fff}
@media(max-width:1100px){.related-product-card{flex-basis:calc((100% - 24px)/3);grid-template-columns:110px minmax(0,1fr)}.related-product-thumb{width:110px;height:96px}.related-product-card>b{grid-column:2;justify-self:start}}
