const productCatalog=Object.fromEntries(productCatalogRaw.map(([categorySlug,brands])=>[categorySlug,brands.map(([slug,officialUrl,images])=>({name:portfolioBrands[slug],slug,officialUrl,images}))]));
Object.values(productCatalog).flat().forEach(brand=>brand.images.forEach(image=>{I[image]=image}));
function catalogSlug(value){return value.toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/ğ/g,'g').replace(/ş/g,'s').replace(/ç/g,'c').replace(/ö/g,'o').replace(/ü/g,'u').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function imageSource(image){return I[image]||image||''}
function catalogCard(item,href,image,label){const labelClass=label.startsWith('Koleksiyon')?'collection-label':'product-label';return `<a href="#${href}" class="product-card catalog-card" style="background-image:linear-gradient(0deg,rgba(0,0,0,.7),transparent),url(${imageSource(image)})"><div><h3>${item.name}</h3><span class="catalog-card-label ${labelClass}">${label}</span></div></a>`}
function productCategoryPage(slug){const category=products.find(x=>x.slug===slug)||products[0];const brands=productCatalog[category.slug]||[];const breadcrumb=`<nav class="hero-breadcrumb" aria-label="Sayfa yolu"><a href="#/urunler">Ürünler</a><span>•</span><strong>${category.name}</strong></nav>`;return hero('/urunler',category.image,category.name,category.name+' koleksiyonlarını keşfedin',breadcrumb)+`<section class="section catalog-section"><p class="kicker">MARKALAR & KOLEKSİYONLAR</p><h2>${category.name}</h2><p class="lead">Seçkin markaları ve bu ürün grubuna ait koleksiyonları inceleyin.</p><div class="catalog-grid">${brands.map(brand=>catalogCard(brand,'/urunler/'+category.slug+'/'+brand.slug,brand.images[0]||category.image,'Görüntüle')).join('')}</div></section>`+cta('Projeniz İçin Doğru Ürünü Birlikte Seçelim')+footer()}
function relatedProducts(category,brand){const items=(productCatalog[category.slug]||[]).filter(item=>item.slug!==brand.slug);if(!items.length)return'';const controls=items.length>2?`<div class="related-products-actions"><button type="button" data-related-prev aria-label="Önceki benzer markalar"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 5 8 12l7 7"/></svg></button><button type="button" data-related-next aria-label="Sonraki benzer markalar"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button></div>`:'';return `<section class="section related-products"><div class="related-products-head"><div><p class="kicker">BENZER ÜRÜNLER</p><h2>Benzer Ürünleri Keşfedin</h2></div>${controls}</div><div class="related-products-grid" data-related-track>${items.map(item=>`<a class="related-product-card" href="#/urunler/${category.slug}/${item.slug}"><span class="related-product-thumb" aria-hidden="true" style="background-image:url(${imageSource(item.images[0]||category.image)})"></span><div class="related-product-card-copy"><small>${category.name}</small><h3>${item.name}</h3></div><b>İnceleyin</b></a>`).join('')}</div></section>`}
function productGalleryImages(primary){const pool=['vanity-v2.png','basin-v2.png','showroom-v2.png','spa-v2.png','home-hero-v2.png'];return [primary,...pool.filter(image=>image!==primary)].slice(0,4)}
function productGallery(item){const images=item.gallery&&item.gallery.length?item.gallery:[item.image],galleryType=item.galleryType||'ürün';return `<div class="product-gallery" data-product-gallery><div class="product-gallery-stage" data-gallery-stage><img data-gallery-main src="${imageSource(images[0])}" alt="${item.name} ana ${galleryType} görseli"><span class="product-gallery-lens" data-gallery-lens aria-hidden="true"></span><button type="button" class="product-gallery-nav product-gallery-prev" data-gallery-prev aria-label="Önceki ${galleryType} görseli"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 5-7 7 7 7" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></button><button type="button" class="product-gallery-nav product-gallery-next" data-gallery-next aria-label="Sonraki ${galleryType} görseli"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></button></div><div class="product-gallery-zoom" data-gallery-zoom aria-hidden="true"></div><div class="product-gallery-thumbs" aria-label="${item.name} ${galleryType} görselleri">${images.map((image,index)=>`<button type="button" class="product-gallery-thumb${index===0?' active':''}" data-gallery-image="${image}" aria-label="${item.name} görsel ${index+1}" aria-pressed="${index===0?'true':'false'}"><img src="${imageSource(image)}" alt=""></button>`).join('')}</div></div>`}
const productBrandProjectCopy={
laufen:'Banyo ürünleri seçilirken günlük kullanım, mekânın yerleşimi ve diğer banyo elemanlarıyla uyum birlikte değerlendirilmelidir. Koleksiyonlar arasındaki ölçü, form ve yüzey seçenekleri projeye uygun bir bütün oluşturmak için incelenebilir.',
'glass-design':'Lavabo ve tamamlayıcı ürünler, banyonun genel tasarım diliyle birlikte ele alınabilir. Form, renk ve malzeme seçimi yapılırken tezgâh, armatür ve kullanım alanıyla uyumun değerlendirilmesi önemlidir.',
'iris-ceramica':'Seramik yüzeylerin renk, doku ve desen seçenekleri mekânın atmosferini belirleyen unsurlardır. Koleksiyon seçimi sırasında kaplanacak alan, diğer malzemelerle ilişki ve uygulama koşulları birlikte değerlendirilmelidir.',
fiandre:'Büyük ebatlı yüzey seçenekleri, mimari projelerde malzeme bütünlüğü açısından değerlendirilebilir. Ölçü, yüzey ve uygulama alternatifleri koleksiyona göre değişebileceği için seçim öncesinde ilgili ürün bilgileri incelenmelidir.',
'ceramica-cielo':'Vitrifiye ve banyo elemanlarının formu, rengi ve yerleşimi mekânın karakteriyle birlikte düşünülebilir. Koleksiyon seçimi yapılırken kullanım ihtiyaçları, montaj koşulları ve tamamlayıcı ürünlerle uyum dikkate alınmalıdır.',
'cea-design':'Armatür seçiminde tasarımın yanı sıra kullanım noktası, yerleşim ve diğer banyo elemanlarıyla uyum önem taşır. Ürün serisine göre değişebilen form ve uygulama seçenekleri projenin ihtiyaçları doğrultusunda incelenmelidir.',
emilgroup:'Seramik yüzey seçimi, projenin genel malzeme ve tasarım yaklaşımıyla birlikte ele alınabilir. İlgili koleksiyonun renk, doku, ölçü ve kullanım seçenekleri değerlendirilerek mekâna uygun alternatifler belirlenebilir.',
emilceramica:'Doğal malzemelerden ilham alan renk ve doku seçenekleri, farklı mekân kurgularında değerlendirilebilir. Yüzeylerin diğer kaplama ve mobilyalarla ilişkisi, kullanım amacı ve uygulama koşulları seçim sürecine yön verebilir.',
ergon:'Malzeme, yüzey ve tasarım seçenekleri; konut, otel ve ticari alan projelerinde farklı estetik yaklaşımlara göre değerlendirilebilir. Ölçü, renk ve uygulama alternatifleri ürün serisine göre değişebileceği için mekânın kullanım amacı ve uygulama koşulları birlikte ele alınmalıdır.',
provenza:'Malzeme karakteri, renk ve yüzey dokusu mekânın tasarım diliyle birlikte değerlendirilebilir. Koleksiyon seçimi yapılırken kaplanacak alanın ölçeği, diğer malzemelerle uyum ve kullanım koşulları dikkate alınmalıdır.',
viva:'Seramik koleksiyonlarının renk ve yüzey seçenekleri, projede hedeflenen tasarım yaklaşımını tamamlamak için incelenebilir. Ölçü ve uygulama alternatifleri değerlendirilirken mekânın işlevi ve diğer malzemelerle uyum göz önünde bulundurulmalıdır.',
level:'Büyük ebatlı yüzeyler, projenin genel malzeme dili ve uygulama alanıyla birlikte değerlendirilebilir. İlgili koleksiyonun ölçü, yüzey ve uygulama bilgileri incelenerek tasarım hedeflerine uygun seçenekler belirlenmelidir.'
};
function productBrandPage(categorySlug,brandSlug){const category=products.find(x=>x.slug===categorySlug)||products[0];const brand=(productCatalog[category.slug]||[]).find(x=>x.slug===brandSlug);if(!brand)return productCategoryPage(category.slug);const breadcrumb=`<nav class="hero-breadcrumb" aria-label="Sayfa yolu"><a href="#/urunler">Ürünler</a><span>•</span><a href="#/urunler/${category.slug}">${category.name}</a><span>•</span><strong>${brand.name}</strong></nav>`;const context=category.name+' | '+brand.name;const item={name:brand.name,image:brand.images[0]||category.image,gallery:brand.images,category:category.name,brand:brand.name,context,officialUrl:brand.officialUrl,breadcrumb,description:`${brand.name}, ${portfolioBrandDescriptions[brand.slug].replace(/\.$/,'').replace(/^./,letter=>letter.toLocaleLowerCase('tr-TR'))} sunar. ${category.name} ürün grubundaki seçenekler, projenin tasarım dili ve kullanım ihtiyaçlarıyla birlikte değerlendirilebilir.`,secondary:productBrandProjectCopy[brand.slug],closing:'Güncel koleksiyonları ve kategoriye ait seçenekleri incelemek için markanın resmî ürün sayfasına geçebilirsiniz. Projenizin ihtiyaçlarına uygun alternatifleri değerlendirmek ve seçim süreci hakkında bilgi almak için Likya Yapı ekibiyle iletişime geçebilirsiniz.'};return detail(item,'product',relatedProducts(category,brand))}

