const route=(href,label,active)=>`<a href="#${href}" class="nav-page-title ${active===href?'active':''}">${label}</a>`;
function header(active){return `<header class="header"><a href="#/" class="logo" aria-label="Ana sayfaya dön"><img src="${I['likya-logo.svg']}" alt="Likya Yapı"></a><nav aria-label="Ana menü">${route('/hakkimizda','Hakkımızda',active)}${route('/urunler','Ürünler',active)}${route('/markalar','Markalar',active)}${route('/referanslar','Referanslar',active)}${route('/profesyoneller','Profesyonel Çözümler',active)}${route('/blog','Blog',active)}${route('/iletisim','İletişim',active)}</nav><button type="button" class="lang" aria-label="Aktif dil: Türkçe" title="Türkçe"><span>TR</span><svg class="lang-flag" viewBox="0 0 30 20" role="img" aria-label="Türk bayrağı"><rect width="30" height="20" fill="#E30A17"/><circle cx="12" cy="10" r="5.6" fill="#fff"/><circle cx="13.7" cy="10" r="4.5" fill="#E30A17"/><path d="m19.2 10 2.7-.88-1.67 2.3v-2.84l1.67 2.3z" fill="#fff"/></svg></button></header>`}
function hero(active,image,title,text,breadcrumb=''){const innerHero=active!=='/'?' inner-hero':'';return `<section class="hero${innerHero}" style="background-image:linear-gradient(90deg,rgba(15,12,10,.82),rgba(15,12,10,.08)),url(${imageSource(image)})">${header(active)}${breadcrumb}<div class="hero-copy"><h1>${title}</h1>${active==='/'?'<a class="hero-link" href="#/urunler">Koleksiyonları Keşfedin →</a>':'<p>'+text+'</p>'}</div></section>`}
function footer(){return `<footer class="footer"><div><a href="#/" class="footer-logo"><img src="${I['likya-logo.svg']}" alt="Likya Yapı"></a><p>Mekanlara ilham veren<br>seçkin tasarımlar.</p></div><div><h4>İLETİŞİM</h4><div class="footer-contact"><a class="footer-contact-item" href="mailto:info@likyayapi.com.tr"><span class="footer-contact-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="2"></rect><path d="m4 7 8 6 8-6"></path></svg></span><span>info@likyayapi.com.tr</span></a><a class="footer-contact-item" href="tel:+902324639994"><span class="footer-contact-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.18 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.12.9.34 1.78.65 2.61a2 2 0 0 1-.45 2.11L8.04 9.71a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.83.31 1.71.53 2.61.65A2 2 0 0 1 22 16.92z"></path></svg></span><span>+90 (232) 463 99 94–95</span></a><div class="footer-contact-item"><span class="footer-contact-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0z"></path><circle cx="12" cy="10" r="2.5"></circle></svg></span><p>Cumhuriyet Bulvarı No:212/A<br>Alsancak / İzmir</p></div></div></div><div><h4>KURUMSAL</h4><a href="#/hakkimizda">Hakkımızda</a><a href="#/referanslar">Referanslar</a><a href="#/profesyoneller">Profesyonel Çözümler</a><a href="#/kataloglar">Kataloglar</a><a href="#/iletisim">İletişim</a></div><div><h4>BİZİ TAKİP EDİN</h4><div class="socials"><a href="https://www.instagram.com/likyayapi/" target="_blank" rel="noopener" aria-label="Instagram"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5"></rect><circle cx="12" cy="12" r="4"></circle><circle cx="17.4" cy="6.6" r="1"></circle></svg></a><a href="https://www.linkedin.com/in/likya-yapi-9586a4176/" target="_blank" rel="noopener" aria-label="LinkedIn"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="4"></rect><path d="M8 10v7M8 7.2v.1M12 17v-4a3 3 0 0 1 6 0v4M12 10v7"></path></svg></a><a href="https://tr-tr.facebook.com/people/Likya-YAPI/100077457622130/" target="_blank" rel="noopener" aria-label="Facebook"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"></circle><path d="M9.8 19c.7-2.1 1-3.2 1.4-5.1-.7-1.4.1-4.2 1.8-4.2 1.3 0 1.8 1 1.8 2.1 0 1.3-.8 3.2-1.2 5-.3 1.5.8 2.7 2.2 2.7 2.7 0 4.4-3.4 4.4-7.5 0-3.1-2.5-5.5-6.2-5.5-4.2 0-6.8 3.1-6.8 6.5 0 1.2.4 2.6 1.1 3.3"></path></svg></a></div></div><div class="legal">© 2026 Likya Yapı. Tüm hakları saklıdır.<span><a href="#/gizlilik-politikasi">Gizlilik Politikası</a><a href="#/kullanim-sartlari">Kullanım Şartları</a><a href="#/kvkk">KVKK</a><a href="#/cerez-politikasi">Çerez Politikası</a></span></div></footer>`}
function cta(title='Projenizi Birlikte Şekillendirelim'){return `<section class="cta"><div><h2>${title}</h2><a href="#/iletisim">Bizimle İletişime Geçin</a></div><img src="${I['basin-v2.png']}" alt="Doğal taş lavabo detayı"></section>`}
function card(item,kind){const href=kind==='product'?'/urunler/':'/referanslar/';if(kind==='product')return `<a href="#${href+item.slug}" class="product-card filter-item" data-category="${item.category}" style="background-image:linear-gradient(0deg,rgba(0,0,0,.65),transparent),url(${imageSource(item.image)})"><div><h3>${item.name}</h3>${item.location?'<p>'+item.location+'</p>':''}<span>Görüntüle</span></div></a>`;const hoverImage=productGalleryImages(item.image)[1];return `<a href="#${href+item.slug}" class="reference-card filter-item" data-category="${item.category}"><span class="reference-card-media" aria-hidden="true"><img class="reference-card-image reference-card-image-primary" src="${imageSource(item.image)}" alt=""><img class="reference-card-image reference-card-image-hover" src="${imageSource(hoverImage)}" alt=""></span><span class="reference-card-shade" aria-hidden="true"></span><div><div class="reference-card-copy"><h3>${item.name}</h3>${item.location?'<p>'+item.location+'</p>':''}</div><span>Görüntüle</span></div></a>`}
