{name:'Provenza',url:'https://www.emilgroup.com/collections/brand/provenza/',color:'#111111',logo:'<img src="/assets/brands/provenza.png" alt="" style="display:block;width:auto;height:auto;max-width:72%;max-height:64px;margin:auto;filter:brightness(0)">'},
