];return `<section class="brands-carousel" id="markalar"><div class="brands-story"><div class="brands-story-copy"><p class="kicker">MARKALAR</p><h2>Dünyanın Seçkin Markaları</h2><p>Global ölçekteki seçkin markaların güvenilir temsilcisi.</p><a class="brands-discover" href="#/markalar">Markaları Keşfedin</a></div><img class="brands-story-image" src="${I['showroom-v2.png']}" alt="Likya Yapı seçkin markalar showroomu"><div class="brands-carousel-bar" id="marka-logolari"><div class="brands-carousel-actions"><button type="button" data-brand-prev aria-label="Önceki markalar"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 5 8 12l7 7"/></svg></button><button type="button" data-brand-next aria-label="Sonraki markalar"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button></div></div></div><div class="brands-carousel-window"><div class="brands-carousel-track">${brands.map(brand=>`<a class="brand-logo-card" style="--brand-color:${brand.color}" href="${brand.url}" target="_blank" rel="noopener" aria-label="${brand.name} resmi web sitesini yeni sekmede aç"><span class="brand-logo">${brand.logo}</span></a>`).join('')}</div></div></section>`}
