];return hero('/markalar','showroom-v2.png','Markalar','Dünyanın seçkin üreticilerini Likya Yapı güvencesiyle keşfedin.')+`<section class="section"><div class="brands-page-intro"><div><p class="kicker">SEÇKİN İŞ BİRLİKLERİ</p><h2>Tasarımın Güçlü İmzaları</h2></div><p class="lead">Banyo, yüzey ve mimari çözüm alanlarında öne çıkan markaları; doğru ürün seçimi, proje deneyimi ve uzman desteğimizle bir araya getiriyoruz.</p></div><div class="brand-page-grid">${brands.map((brand,i)=>`<a class="brand-page-card" style="--brand-color:${brand.color}" href="${brand.url}" target="_blank" rel="noopener" aria-label="${brand.name} resmi web sitesini yeni sekmede aç"><span class="brand-logo">${brand.logo}</span></a>`).join('')}</div><p class="brand-page-note">Bir markanın resmî web sitesini ziyaret etmek için logosuna tıklayın.</p></section>`+cta('Projeniz İçin Doğru Markayı Birlikte Seçelim')+footer()}
function home(){const cats=products.slice(0,4);return hero('/','home-hero-v2.png','Mekanlara Değer Katan Seçkin Tasarımlar','')+`<section class="split intro"><div><p class="kicker">LİKYA YAPI</p><h2>Tasarımın <br>Zamansız Hali</h2><p>Likya Yapı, yaşam alanlarınıza zarafet ve işlevsellik katan özgün ürünler sunar. İlham veren tasarımları ve yaratıcı çözümleriyle estetik ile sürdürülebilirliği bir araya getiriyoruz.</p><a href="#/hakkimizda">Hakkımızda</a></div><img src="${I['basin-v2.png']}" alt="Tasarım lavabo ve armatür"></section><section class="section home-product-groups" data-home-product-groups><div class="section-head"><h2>Öne Çıkan Ürün Grupları</h2><a href="#/urunler">Tüm Ürünleri İnceleyin</a></div><div class="category-grid" data-home-product-track>${cats.map(x=>card(x,'product').replace('product-card','image-card')).join('')}</div><template data-home-product-extra>${products.slice(4,8).map(x=>card(x,'product').replace('product-card','image-card').replace('class="','data-home-product-extra-card class="')).join('')}</template><div class="home-product-controls" aria-label="Ürün grupları gezinme"><button type="button" data-home-product-prev aria-label="Önceki ürün grupları"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M15 5 8 12l7 7"/></svg></button><button type="button" data-home-product-next aria-label="Sonraki ürün grupları"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button><span class="home-product-status" data-home-product-status aria-live="polite" aria-atomic="true"></span></div></section><section class="section projects"><div class="section-head"><h2>Seçili Projeler</h2><a href="#/referanslar">Tüm Projeleri İnceleyin</a></div><div class="project-grid">${projects.slice(0,3).map(x=>`<a href="#/referanslar/${x.slug}"><img src="${I[x.image]}" alt="${x.name}"><h3>${x.name}</h3><p>${x.location}</p><span>Görüntüle</span></a>`).join('')}</div></section>`+brandsCarousel()+`<section class="split showroom"><img src="${I['showroom-v2.png']}" alt="İzmir showroom"><div><h2>İzmir Showroom</h2><p>Ürün koleksiyonlarımızı yerinde keşfetmek ve uzman ekibimizden ilham almak için sizi showroom’umuza bekliyoruz.</p><a href="#/iletisim">Randevu Alın</a></div></section>`+footer()}
function filters(items,kind){const cats=['Tümü',...new Set(items.map(x=>x.category))];return `<div class="filters">${cats.map((x,i)=>`<button class="${i===0?'selected':''}" data-filter="${x}">${x}</button>`).join('')}</div><div class="${kind==='product'?'products-grid':'reference-grid'}">${items.map(x=>card(x,kind)).join('')}</div>`}
function productsPage(){return hero('/urunler','vanity-v2.png','Ürünler','Mekanlara değer katan seçkin koleksiyonlar')+`<section class="section product-index-section"><p class="kicker">KOLEKSİYONLAR</p><h2>Malzeme, Tasarım ve İşlev</h2><p class="lead">Dünyanın seçkin markalarını, zamansız tasarım ve üstün malzeme kalitesiyle bir araya getiriyoruz.</p>${filters(products,'product')}</section>`+cta('Projeniz İçin Doğru Ürünü Birlikte Seçelim')+footer()}
function about(){return hero('/hakkimizda','vanity-v2.png','Hakkımızda','Tasarım, kalite ve güven üzerine kurulu bir yolculuk.')+`<section class="split intro"><div><p class="kicker">BİZ KİMİZ</p><h2>Mekanlara Değer Katan Birikim</h2><p>Likya Yapı, seçkin uluslararası markaların üstün kaliteli ürünlerini mimari vizyonla buluşturan, yaşam alanlarına değer katan İzmir merkezli bir çözüm ortağıdır.</p></div><img src="${I['basin-v2.png']}" alt="Doğal taş ve armatür detayları"></section><section class="dark values section"><h2>Seçkin Tasarımın İzinde</h2><div class="three"><article><b>◇</b><h3>Kalite</h3><p>Uzun yıllar mekanlara değer katan ürünleri seçiyoruz.</p></article><article><b>△</b><h3>Tasarım</h3><p>Estetik ve işlevselliği bir araya getiren ürünleri sunuyoruz.</p></article><article><b>♢</b><h3>Güven</h3><p>Şeffaf iletişim ve sorumlu çözüm ortaklığı sunuyoruz.</p></article></div><img class="wide-image" src="${I['showroom-v2.png']}" alt="Likya Yapı malzeme showroomu"></section><section class="section about-process"><h2>Mimari Vizyonla Bütünleşen Çözümler</h2><p class="lead">Her projeyi mekanın ihtiyaçlarını ve tasarım dilini anlayarak ele alıyor, doğru ürün seçimini güvenilir bir süreçle sonuca taşıyoruz.</p><div class="steps"><article><b>01</b><h3>İhtiyacı Anlamak</h3><p>Mekanın kullanım amacını, ölçüsünü ve tasarım beklentilerini birlikte değerlendiriyoruz.</p></article><article><b>02</b><h3>Doğru Ürünü Seçmek</h3><p>Malzeme, yüzey ve teknik özellikleri projeye uygun seçkin alternatiflerle buluşturuyoruz.</p></article><article><b>03</b><h3>Mekana Değer Katmak</h3><p>Estetik, işlevsellik ve uzun ömürlü kullanımı bir araya getiren çözümler sunuyoruz.</p></article></div></section><section class="split showroom"><img src="${I['showroom-v2.png']}" alt="İzmir showroom"><div><h2>İzmir Showroom</h2><p>Koleksiyonlarımızı yakından incelemek ve uzman ekibimizle projeniz için doğru ürünleri belirlemek üzere showroom’umuzu ziyaret edin.</p><a href="#/iletisim">Randevu Alın</a></div></section>`+cta()+footer()}
function references(){return hero('/referanslar','project-v2.png','Referanslar','Seçkin projelere değer katan çözümler')+`<section class="section references-index-section"><p class="kicker">PROJELER</p><h2>Mekanlara İz Bırakan Projeler</h2><p class="lead">Otel, konut, ofis ve özel yaşam projelerinde seçkin markaları doğru malzeme ve güçlü tasarım anlayışıyla buluşturuyoruz.</p>${filters(projects,'project')}<h2 class="other-title">Diğer Referanslarımız</h2><div class="other-refs">${['Ramada Resort Kuşadası','Liberty Hotels Lykia','Key Hotel','Folkart Boyalık Beach','Swissotel Büyük Efes','Pine Bay Holiday Resort','The Chesme Executive','Sea Homes Paşalimanı'].map(x=>`<div style="border-bottom:1px solid var(--line);padding:14px 0">${x}</div>`).join('')}</div></section>`+cta('Projeniz İçin Birlikte Çalışalım')+footer()}

function professionalMeta(item){const data={
'banyo-dolaplari':{size:'80 / 100 / 120 cm',material:'Doğal kaplama · lake · kompakt yüzey',mount:'Duvara monte veya ayaklı',detail:'Banyo dolapları; estetik, işlevsellik ve akıllı depolama çözümlerini bir araya getirir.'},
'vitrifiye':{size:'50 / 60 / 80 cm',material:'Yüksek dayanımlı vitrifiye seramik',mount:'Tezgah üstü · asma · ankastre',detail:'Armatür deliği, taşma kanalı ve montaj tipine göre farklı teknik seçenekler sunulur.'},
'batarya-armatur':{size:'Standart ve ankastre modüller',material:'Pirinç gövde · PVD yüzey seçenekleri',mount:'Tezgah · duvar · zemin',detail:'Debi, basınç, bağlantı ve kaplama alternatifleri teknik projeye göre seçilir.'},
