};return data[item.technicalKey||item.slug]||{size:'Projeye göre',material:'Koleksiyona göre',mount:'Uygulamaya göre',detail:'Teknik özellikler proje gereksinimlerine göre belirlenir.'}}
function technicalProductCard(item){const m=professionalMeta(item);return `<article class="pro-product-card"><a class="pro-product-image" href="#/urunler/${item.slug}"><img src="${I[item.image]}" alt="${item.name}"></a><div class="pro-product-body"><p class="pro-product-category">${item.category}</p><h3>${item.name}</h3><dl><div><dt>Ölçü</dt><dd>${m.size}</dd></div><div><dt>Malzeme</dt><dd>${m.material}</dd></div><div><dt>Uygulama</dt><dd>${m.mount}</dd></div></dl><a class="pro-detail-link" href="#/urunler/${item.slug}">Teknik Detayları İnceleyin →</a></div></article>`}
function professionals(){return hero('/profesyoneller','project-v2.png','Profesyonel Çözümler','Mimari fikirleri doğru ürün, güçlü teknik destek ve güvenilir çözüm ortaklığıyla buluşturuyoruz.')+`<section class="split pro-intro"><div><p class="kicker">PROFESYONEL ÇÖZÜMLER</p><h2>Projelerinize Özel Çözüm Ortaklığı</h2><p>Mimarlar, iç mimarlar, tasarımcılar ve proje ekipleri için ürün seçiminden uygulama sürecine kadar bütüncül destek sunuyoruz. Seçkin koleksiyonları projenizin dili, ölçeği ve teknik gereksinimleriyle buluşturuyoruz.</p><a href="#/iletisim">Projenizi Bizimle Paylaşın</a></div><img src="${I['showroom-v2.png']}" alt="Likya Yapı profesyonel malzeme danışmanlığı"></section><section class="pro-services section"><p class="kicker">BİRLİKTE ÇALIŞALIM</p><div class="section-head"><h2>Profesyonellere Özel Destek</h2><p>Fikir aşamasından uygulamaya kadar projenizin her adımında yanınızdayız.</p></div><div class="pro-service-grid"><article><span>01</span><h3>Ürün & Malzeme Danışmanlığı</h3><p>Projenizin estetik yaklaşımına, kullanım amacına ve bütçesine uygun ürün alternatiflerini birlikte belirliyoruz.</p></article><article><span>02</span><h3>Teknik Dokümantasyon</h3><p>Ölçü, yüzey, uygulama ve teknik özelliklere ilişkin ihtiyaç duyduğunuz bilgileri proje ekibinizle paylaşıyoruz.</p></article><article><span>03</span><h3>Numune & Proje Desteği</h3><p>Malzeme ve yüzey kararlarını kolaylaştıran numune desteğiyle seçim sürecini daha güvenli hâle getiriyoruz.</p></article></div></section><section class="section pro-process"><div><p class="kicker">ÇALIŞMA SÜRECİ</p><h2>Fikirden Uygulamaya</h2></div><div class="pro-process-list"><article><b>01</b><div><h3>İhtiyacı Anlama</h3><p>Projenin kapsamını, tasarım yaklaşımını ve teknik beklentilerini birlikte değerlendiririz.</p></div></article><article><b>02</b><div><h3>Doğru Ürünü Seçme</h3><p>Koleksiyonlarımız arasından projeye uygun ürün, ölçü ve yüzey seçeneklerini sunarız.</p></div></article><article><b>03</b><div><h3>Uygulama Desteği</h3><p>Seçimlerin doğru uygulanması için proje ve saha sürecinde profesyonel destek sağlarız.</p></div></article></div></section>`+cta('Projenizi Birlikte Şekillendirelim')+footer()}
function contact(){const map='https://www.google.com/maps?cid=991378877089050925';return hero('/iletisim','showroom-v2.png','İletişim','Projeleriniz için doğru çözümleri birlikte belirleyelim')+`<section class="contact section"><div><p class="kicker">BİZE ULAŞIN</p><h2>Bizimle İletişime Geçin</h2><a class="contact-detail" href="tel:+902324639994"><span class="contact-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.18 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.13.96.36 1.9.68 2.8a2 2 0 0 1-.45 2.11L8.09 9.88a16 16 0 0 0 6 6l1.25-1.25a2 2 0 0 1 2.11-.45c.9.32 1.84.55 2.8.68A2 2 0 0 1 22 16.92z"/></svg></span><span class="contact-item-copy"><b>Telefon</b><span>+90 (232) 463 99 94–95</span></span></a><a class="contact-detail" href="mailto:info@likyayapi.com.tr"><span class="contact-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/></svg></span><span class="contact-item-copy"><b>E-Posta</b><span>info@likyayapi.com.tr</span></span></a><a class="contact-detail" href="${map}" target="_blank"><span class="contact-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0z"/><circle cx="12" cy="10" r="2.5"/></svg></span><span class="contact-item-copy"><b>Adres</b><span>Cumhuriyet Bulvarı No:212/A, Alsancak / İzmir</span></span></a></div><div class="contact-form-area"><div class="contact-form-tabs" role="tablist" aria-label="İletişim formu seçimi"><button type="button" class="selected" data-contact-tab="general" role="tab" aria-selected="true"><span>Genel İletişim</span><small>Soru ve bilgi talepleriniz için</small></button><button type="button" data-contact-tab="professional" role="tab" aria-selected="false"><span>Profesyonel Proje Talebi</span><small>Mimarlar ve proje ekipleri için</small></button></div><div class="contact-choice-panel active" data-contact-panel="general"><form class="contact-form"><label>Adınız Soyadınız<input name="ad-soyad" required></label><label>E-Posta Adresiniz<input name="eposta" type="email" required></label><label>Telefon Numaranız<input name="telefon" type="tel"></label><label>Konu<input name="konu" required></label><label>Mesajınız<textarea name="mesaj" rows="5" required></textarea></label><button type="submit">Mesaj Gönder</button><p class="form-success hidden">Teşekkür ederiz. Mesajınız başarıyla alındı.</p></form></div><div class="contact-choice-panel" data-contact-panel="professional"><form class="contact-form professional-form"><p class="form-panel-intro">Projenizi paylaşın, ihtiyaçlarınıza uygun ürün ve çözüm seçeneklerini birlikte belirleyelim.</p><div class="form-grid"><label>Adınız Soyadınız<input name="ad-soyad" required></label><label>Firma / Ofis Adı<input name="firma" required></label><label>E-Posta Adresiniz<input name="eposta" type="email" required></label><label>Telefon Numaranız<input name="telefon" type="tel" required></label><label>Mesleğiniz<select name="meslek" required><option value="">Seçiniz</option><option>Mimar</option><option>İç Mimar</option><option>Proje Yöneticisi</option><option>Yüklenici / Uygulamacı</option><option>Diğer</option></select></label><label>Proje Türü<select name="proje-turu" required><option value="">Seçiniz</option><option>Konut</option><option>Otel</option><option>Ticari Alan</option><option>Ofis</option><option>Özel Proje</option></select></label><label>Proje Konumu<input name="konum" placeholder="Şehir / İlçe"></label><label>İlgilendiğiniz Ürün Grubu<select name="urun-grubu"><option value="">Seçiniz</option>${[...new Set(products.map(x=>x.category))].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="full">Projeniz Hakkında<textarea name="proje-detayi" rows="5" placeholder="Projenizin kapsamını, ihtiyaçlarınızı ve varsa ölçü bilgilerini paylaşabilirsiniz." required></textarea></label></div><button type="submit">Proje Talebini Gönder</button><p class="form-success hidden">Teşekkür ederiz. Proje talebiniz başarıyla alındı.</p></form></div></div></section><section class="showroom-map"><img src="${I['showroom-v2.png']}" alt="Likya Yapı İzmir showroom"><div class="map-panel"><iframe title="Likya Yapı İzmir Showroom konumu" src="https://www.google.com/maps?q=38.436341,27.141539&z=17&output=embed" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe><a class="map-open-link" href="${map}" target="_blank" rel="noopener">Haritalarda Aç <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M14 5h5v5"/><path d="M10 14 19 5"/><path d="M19 13v6H5V5h6"/></svg></a><div><p class="kicker">İZMİR KÖRFEZİ · ALSANCAK</p><h2>İzmir Showroom</h2></div></div></section><section class="showroom-invite"><h2>Koleksiyonları yakından keşfedin.</h2><div class="showroom-invite-copy"><p>Sizi İzmir showroom’umuzda ağırlamaktan memnuniyet duyarız.</p><a class="showroom-invite-action" href="mailto:info@likyayapi.com.tr?subject=Showroom%20Randevu%20Talebi">Randevu Talebi</a></div></section>`+footer()}
function detail(item,kind,afterDetail=''){const product=kind==='product';const m=product?professionalMeta(item):null;const galleryItem=item.gallery&&item.gallery.length?{...item,galleryType:'ürün'}:{...item,gallery:productGalleryImages(item.image),galleryType:product?'ürün':'proje'};const copy=product?(item.description||m.detail):item.name+' projesinde tasarım dili, malzeme kalitesi ve kullanım ihtiyaçları birlikte ele alındı. Seçkin ürün grupları projenin mimari karakteriyle uyumlu, bütüncül bir yaklaşımla değerlendirildi.';const actions=product?`<div class="detail-actions"><a href="${item.officialUrl}" target="_blank" rel="noopener">Koleksiyonları İnceleyin</a><a href="#/iletisim" data-product-inquiry>Bilgi Alın</a></div>`:`<div class="detail-actions"><a href="#/iletisim">Benzer Bir Proje İçin Görüşün</a><a href="#/referanslar">Tüm Projelere Dönün</a></div>`;return hero(product?'/urunler':'/referanslar',item.image,item.name,product?item.category+' koleksiyonunu keşfedin':item.location+' · '+item.category,product?(item.breadcrumb||''):'')+`<section class="split detail-section ${product?'product-detail-enhanced':'reference-detail-enhanced'}"${product?` data-product-context="${item.context}"`:''}><div><p class="kicker">${product?item.category+' · ÜRÜN DETAYI':'SEÇİLİ PROJE'}</p><h2>${product?item.name:'Mekana Değer Katan Çözüm'}</h2><p>${copy}</p>${product&&item.secondary?`<p>${item.secondary}</p>`:''}${product&&item.closing?`<p>${item.closing}</p>`:''}${actions}</div>${productGallery(galleryItem)}</section>`+afterDetail+cta(product?'Projeniz İçin Doğru Ürünü Birlikte Seçelim':'Projeniz İçin Birlikte Çalışalım')+footer()}
function legalPage(path){const names={'/gizlilik-politikasi':'Gizlilik Politikası','/kullanim-sartlari':'Kullanım Şartları','/kvkk':'KVKK Aydınlatma Metni','/cerez-politikasi':'Çerez Politikası'};const title=names[path]||'Bilgilendirme';return `<section class="legal-hero" style="background-image:linear-gradient(90deg,rgba(15,12,10,.82),rgba(15,12,10,.28)),url('${I['showroom-v2.png']}' )">${header('')}<div><h1>${title}</h1></div></section><section class="section legal-copy"><h2>${title}</h2><p>Likya Yapı, ziyaretçilerinin kişisel verilerinin ve gizliliğinin korunmasına önem verir. Ayrıntılı bilgi ve talepleriniz için <a href="mailto:info@likyayapi.com.tr">info@likyayapi.com.tr</a> adresinden bizimle iletişime geçebilirsiniz.</p></section>`+footer()}
