];
function blogItemsPerPage(){return window.matchMedia('(min-width: 561px) and (max-width: 900px)').matches?8:9}
function blogPage(){const pageCount=Math.ceil(blogPosts.length/blogItemsPerPage());return `<section class="blog-hero" style="background-image:linear-gradient(90deg,rgba(15,12,10,.86),rgba(15,12,10,.32)),url(${I['project-v2.png']})">${header('/blog')}<div><p class="kicker">LİKYA YAPI JOURNAL</p><h1>Blog</h1><p>Mimari, tasarım, malzeme ve yaşam alanlarına dair ilham veren fikirler.</p></div></section><main class="blog-index section"><div class="blog-heading"><div><p class="kicker">GÜNCEL YAZILAR</p><h2>İlham & Uzmanlık</h2></div><p>Seçkin mekanlar oluştururken doğru ürün, malzeme ve tasarım kararlarına eşlik eden içerikler.</p></div><div class="blog-grid">${blogPosts.map((post,index)=>`<article class="blog-card"><a class="blog-card-image" href="#/blog/${post.slug}" aria-label="${post.title}"><img src="${I[post.image]}" alt="${post.title}"><span>${String(index+1).padStart(2,'0')}</span></a><div class="blog-card-copy"><p class="blog-meta">${post.category} · ${post.date}</p><h3><a href="#/blog/${post.slug}">${post.title}</a></h3><p>${post.excerpt}</p><a class="blog-read" href="#/blog/${post.slug}">Devamını Oku <b>→</b></a></div></article>`).join('')}</div><nav class="blog-pagination" aria-label="Blog sayfaları">${Array.from({length:pageCount},(_,index)=>`<button type="button" data-blog-page="${index+1}" aria-label="${index+1}. sayfa">${index+1}</button>`).join('')}<button type="button" data-blog-next aria-label="Sonraki sayfa">→</button></nav></main>`+cta('Projenizi Birlikte Şekillendirelim')+footer()}
function cataloguesPage(){const categories=['Tüm Kataloglar',...new Set(catalogueItems.map(item=>item.category))];return hero('/kataloglar','showroom-v2.png','Kataloglar','Banyo, yüzey ve yaşam alanlarına yönelik seçkin marka kataloglarını keşfedin.')+`<main class="catalogue-archive section"><div class="catalogue-intro"><div><p class="kicker">KATALOG ARŞİVİ</p><h2>Koleksiyonları<br>Kaynağından Keşfedin</h2></div><p>İlgilendiğiniz kategoriyi seçin; güncel koleksiyonları, ürün seçeneklerini ve teknik detayları markaların kendi sayfalarında inceleyin.</p></div><div class="catalogue-layout"><aside class="catalogue-filters" aria-label="Katalog kategorileri"><div class="catalogue-filter-heading"><span>Kategoriler</span><small>${catalogueItems.length}</small></div>${categories.map((category,index)=>`<button type="button" data-catalogue-filter="${category}" class="${index===0?'selected':''}" aria-pressed="${index===0?'true':'false'}"><span>${category}</span><small>${category==='Tüm Kataloglar'?catalogueItems.length:catalogueItems.filter(item=>item.category===category).length}</small></button>`).join('')}</aside><section class="catalogue-results"><div class="catalogue-results-head"><div><p class="kicker">GÜNCEL SEÇKİ</p><h3 data-catalogue-title>Tüm Kataloglar</h3></div><span data-catalogue-count>${catalogueItems.length} katalog</span></div><div class="catalogue-card-grid">${catalogueItems.map(item=>`<article class="catalogue-card" data-catalogue-category="${item.category}"><a class="catalogue-cover" href="${item.url}" target="_blank" rel="noopener noreferrer" aria-label="${item.brand} ${item.title} sayfasını yeni sekmede aç"><img src="${I[item.image]}" alt="${item.brand} ${item.title} katalog kapak görseli" loading="lazy"><span>MARKA SİTESİ</span><div><small>${item.brand}</small><strong>${item.title}</strong></div></a><div class="catalogue-card-copy"><p>${item.brand}</p><h4>${item.title}</h4><div><span>${item.category}</span><a href="${item.url}" target="_blank" rel="noopener noreferrer">Kataloğu İncele <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 17 17 7M9 7h8v8"/></svg></a></div></div></article>`).join('')}</div><p class="catalogue-source-note">Katalog bağlantıları ilgili markaların resmî web sitelerinde yeni sekmede açılır.</p></section></div></main>`+cta('Koleksiyon Seçiminde Uzman Desteği Alın')+footer()}
function blogDetail(post){return `<section class="blog-detail-hero" style="background-image:linear-gradient(90deg,rgba(18,14,12,.86) 0%,rgba(18,14,12,.62) 48%,rgba(18,14,12,.28) 100%),url(${I[post.image]})">${header('/blog')}<div><p class="blog-meta">${post.category} · ${post.date}</p><h1>${post.title}</h1></div></section><main class="blog-detail section"><article><img class="blog-detail-image" src="${I[post.image]}" alt="${post.title}"><p class="blog-lead">${post.excerpt}</p><h2>Mekana Bütüncül Bakın</h2><p>İyi tasarlanmış bir mekan, yalnızca güzel ürünlerin bir araya gelmesiyle değil; ölçü, malzeme, ışık ve kullanım alışkanlıklarının aynı bütün içinde değerlendirilmesiyle oluşur. Bu nedenle seçim sürecinin ilk adımı mekanın ihtiyaçlarını doğru tanımlamaktır.</p><p>Yüzeylerin birbiriyle kurduğu ilişki, ürünlerin kullanım konforu ve uzun ömürlü olması tasarım kararlarının merkezinde yer almalıdır. Sade bir renk paleti, doğal dokular ve doğru oranlar zamansız bir görünüm oluşturur.</p><h2>Doğru Ürün, Doğru Ölçek</h2><p>Ürün seçerken yalnızca görünümü değil, teknik ölçüleri ve uygulama koşullarını da birlikte ele almak gerekir. Numuneleri gün ışığında incelemek ve alternatifleri mekanın gerçek ölçüleri üzerinden karşılaştırmak karar sürecini kolaylaştırır.</p><blockquote>“Zamansız mekanlar, dikkat çeken parçalardan önce doğru kurulmuş bir bütünlüğe dayanır.”</blockquote><p>Likya Yapı showroom’unda koleksiyonları yakından inceleyebilir, projenize uygun ürün ve yüzey seçeneklerini uzman ekibimizle birlikte değerlendirebilirsiniz.</p></article><aside class="blog-sidebar"><div><p class="kicker">PROJENİZ İÇİN</p><h3>Birlikte değerlendirelim.</h3><p>Ürün ve malzeme seçiminde uzman ekibimizden destek alın.</p><a href="#/iletisim">İletişime Geçin →</a></div><div><p class="kicker">SON YAZILAR</p>${blogPosts.filter(item=>item.slug!==post.slug).slice(0,3).map(item=>`<a class="blog-side-post" href="#/blog/${item.slug}"><span>${item.date}</span>${item.title}</a>`).join('')}</div></aside></main>`+footer()}
function render(){const path=(window.__likyaHash.slice(1)||'/').split('?')[0];let content;if(path==='/')content=home();else if(path==='/urunler')content=productsPage();else if(path==='/markalar')content=brandsPage();else if(path==='/hakkimizda')content=about();else if(path==='/referanslar')content=references();else if(path==='/profesyoneller')content=professionals();else if(path==='/kataloglar')content=cataloguesPage();else if(path==='/blog')content=blogPage();else if(path.startsWith('/blog/'))content=blogDetail(blogPosts.find(x=>x.slug===path.split('/').pop())||blogPosts[0]);else if(path==='/iletisim')content=contact();else if(path.startsWith('/urunler/')){const parts=path.split('/').filter(Boolean);if(parts.length===2)content=productCategoryPage(parts[1]);else content=productBrandPage(parts[1],parts[2])}else if(path.startsWith('/referanslar/'))content=detail(projects.find(x=>x.slug===path.split('/').pop())||projects[0],'project');else content=legalPage(path);document.getElementById('app').innerHTML=content;window.scrollTo(0,0);bind()}
function bind(){const brandTrack=document.querySelector('.brands-carousel-track');if(brandTrack){const move=dir=>brandTrack.scrollBy({left:dir*brandTrack.clientWidth*.75,behavior:'smooth'});document.querySelector('[data-brand-prev]').addEventListener('click',()=>move(-1));document.querySelector('[data-brand-next]').addEventListener('click',()=>move(1));document.querySelectorAll('.brand-logo-card').forEach(card=>card.addEventListener('click',()=>{document.querySelectorAll('.brand-logo-card').forEach(item=>item.classList.remove('selected'));card.classList.add('selected')}))}document.querySelectorAll('[data-product-gallery]').forEach(gallery=>{const stage=gallery.querySelector('[data-gallery-stage]');const main=gallery.querySelector('[data-gallery-main]');const thumbs=[...gallery.querySelectorAll('[data-gallery-image]')];thumbs.forEach(thumb=>thumb.addEventListener('click',()=>{main.src=imageSource(thumb.dataset.galleryImage);thumbs.forEach(item=>{const active=item===thumb;item.classList.toggle('active',active);item.setAttribute('aria-pressed',active?'true':'false')})}));stage.addEventListener('mousemove',event=>{if(window.matchMedia('(hover:none)').matches)return;const box=stage.getBoundingClientRect();main.style.transformOrigin=`${(event.clientX-box.left)/box.width*100}% ${(event.clientY-box.top)/box.height*100}%`;stage.classList.add('is-zooming')});stage.addEventListener('mouseleave',()=>{stage.classList.remove('is-zooming');main.style.transformOrigin='center'})});document.querySelectorAll('.related-products').forEach(section=>{const track=section.querySelector('[data-related-track]');const prev=section.querySelector('[data-related-prev]');const next=section.querySelector('[data-related-next]');if(!track||!prev||!next)return;const move=direction=>track.scrollBy({left:direction*track.clientWidth,behavior:'smooth'});prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1))});const brandDetail=document.querySelector('[data-brand-detail]');if(brandDetail){document.querySelectorAll('[data-brand-page-card]').forEach(card=>card.addEventListener('click',()=>{document.querySelectorAll('[data-brand-page-card]').forEach(item=>{item.classList.remove('selected');item.setAttribute('aria-pressed','false')});card.classList.add('selected');card.setAttribute('aria-pressed','true');brandDetail.querySelector('[data-brand-detail-name]').textContent=card.dataset.name;brandDetail.querySelector('[data-brand-detail-category]').textContent=card.dataset.category;brandDetail.querySelector('[data-brand-detail-text]').textContent=card.dataset.description;brandDetail.scrollIntoView({behavior:'smooth',block:'center'})}))}document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.classList.remove('selected'));btn.classList.add('selected');document.querySelectorAll('.filter-item').forEach(card=>card.classList.toggle('hidden',btn.dataset.filter!=='Tümü'&&card.dataset.category!==btn.dataset.filter))}));document.querySelectorAll('[data-contact-tab]').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('[data-contact-tab]').forEach(button=>{const active=button===tab;button.classList.toggle('selected',active);button.setAttribute('aria-selected',active)});document.querySelectorAll('[data-contact-panel]').forEach(panel=>panel.classList.toggle('active',panel.dataset.contactPanel===tab.dataset.contactTab))}));document.querySelectorAll('.contact-form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();form.querySelector('.form-success').classList.remove('hidden');form.reset()}))}
function addProjectMeta(){const section=document.querySelector('.reference-detail-enhanced');if(!section||section.querySelector('.reference-project-meta'))return;const copy=section.querySelector(':scope>div');const actions=section.querySelector('.detail-actions');if(!copy||!actions)return;const item=projects.find(project=>window.__likyaHash.endsWith('/'+project.slug))||projects[0];const details={
'folkart-towers':{text:'Folkart Towers projesinde yüksek katlı yaşamın ihtiyaçları, güçlü mimari karakter ve zamansız malzeme seçimleriyle birlikte ele alındı. İç mekanlarda doğal taş etkisi, sıcak ahşap dokular ve akşam kullanımını destekleyen aydınlatma kararları dengeli bir atmosfer oluşturuyor.',scope:'Konut ve ortak yaşam alanları',highlights:'Doğal taş · ahşap dokular · özel detaylar'},
'marriott-hotel':{text:'Marriott Hotel projesinde konuk deneyimini destekleyen, yoğun kullanıma dayanıklı ve bakımı kolay malzeme kararları öne çıkarıldı. Giriş, lobi ve konaklama alanlarında prestijli görünüm ile uzun süreli kullanım dengelendi.',scope:'Otel ve konaklama alanları',highlights:'Lobi çözümleri · dayanıklı yüzeyler · özel üretimler'},
'hyatt-regency':{text:'Hyatt Regency projesinde çağdaş otel kimliğini destekleyen sade, rafine ve işlevsel bir mekan dili oluşturuldu. Farklı kullanım yoğunluklarına sahip alanlar için yüzey, renk ve ürün seçimleri bir bütün olarak değerlendirildi.',scope:'Otel iç mekanları',highlights:'Çağdaş yüzeyler · fonksiyonel çözümler · detay bütünlüğü'},
'swissotel':{text:'Swissotel projesinde konforlu konaklama deneyimini tamamlayan doğal tonlar ve güçlü malzeme kontrastları kullanıldı. Spa ve dinlenme alanlarında sakin, dayanıklı ve kolay bakım sağlayan çözümler ön plana çıkarıldı.',scope:'Otel ve spa alanları',highlights:'Spa çözümleri · doğal tonlar · konfor odaklı tasarım'},
'istinyepark':{text:'İstinyePark projesinde yoğun ziyaretçi trafiğine uyum sağlayan dayanıklı yüzeyler, dikkat çekici malzeme geçişleri ve güçlü yönlendirme etkisi birlikte kurgulandı. Ticari mekanın dinamizmi, seçkin ve bütünlüklü bir tasarım diliyle dengelendi.',scope:'Ticari ve ortak kullanım alanları',highlights:'Yoğun kullanıma uygun yüzeyler · özel ölçüler · güçlü malzeme dili'},
'radisson-blu-resort-spa':{text:'Radisson Blu Resort & Spa projesinde deniz ve tatil atmosferini iç mekanlara taşıyan doğal dokular, sakin renkler ve konfor odaklı ürün seçimleri öne çıktı. Spa ve konaklama alanlarında estetik, dayanıklılık ve kullanım kolaylığı birlikte düşünüldü.',scope:'Resort, otel ve spa alanları',highlights:'Spa çözümleri · doğal dokular · konaklama konforu'},
'ramada-encore-izmir':{text:'Ramada Encore İzmir projesinde şehir otelciliğine uygun, işlevsel ve çağdaş bir iç mekan dili oluşturuldu. Kompakt alanların verimli kullanımı, kolay bakım sağlayan yüzeyler ve sıcak malzeme dokularıyla desteklendi.',scope:'Şehir oteli ve ortak alanlar',highlights:'Kompakt çözümler · kolay bakım · çağdaş yüzeyler'},
'doubletree-by-hilton-sarnic':{text:'DoubleTree by Hilton projesinde markanın konforlu ve güven veren kimliğini destekleyen malzeme seçimleri yapıldı. Giriş ve ortak alanlarda ilk izlenimi güçlendiren yüzeyler, konaklama alanlarında ise dayanıklılık ve kullanım rahatlığı öne alındı.',scope:'Otel, lobi ve konaklama alanları',highlights:'Lobi tasarımı · dayanıklı malzemeler · konfor'},
'boyalik-beach-hotel-spa':{text:'Boyalık Beach Hotel & Spa projesinde sahil atmosferinin ferahlığı, doğal malzemeler ve yumuşak renk geçişleriyle iç mekanlara taşındı. Spa, banyo ve dinlenme alanlarında suya dayanıklı, konforlu ve zamansız çözümler tercih edildi.',scope:'Otel, spa ve ıslak hacimler',highlights:'Spa ve banyo çözümleri · doğal malzemeler · ferah atmosfer'}
}[item.slug]||{text:item.name+' projesinde mimari karakter, kullanım ihtiyaçları ve malzeme seçimi birlikte değerlendirilerek projeye özgü bütünlüklü çözümler oluşturuldu.',scope:item.category+' alanları',highlights:'Malzeme seçimi · özel detaylar · mekan bütünlüğü'};const description=copy.querySelector('h2+p');if(description)description.textContent=details.text;const meta=document.createElement('div');meta.className='reference-project-meta';meta.innerHTML='<div><span>PROJE TÜRÜ</span><b>'+item.category+' projesi</b></div><div><span>LOKASYON</span><b>'+item.location+'</b></div><div><span>ÇÖZÜM KAPSAMI</span><b>'+details.scope+'</b></div><div><span>ÖNE ÇIKANLAR</span><b>'+details.highlights+'</b></div>';copy.insertBefore(meta,actions)}
function bindProjectInquiry(){const button=document.querySelector('.reference-detail-enhanced .detail-actions a:first-child');if(!button)return;button.removeAttribute('href');button.setAttribute('role','button');button.addEventListener('click',()=>{let modal=document.querySelector('.project-inquiry-modal');if(!modal){modal=document.createElement('div');modal.className='project-inquiry-modal';modal.innerHTML='<div class="project-inquiry-panel" role="dialog" aria-modal="true" aria-label="Proje iletişim formu"><button class="project-inquiry-close" type="button" aria-label="Formu kapat">×</button><p class="kicker">PROJE TALEBİ</p><h2>Projenizi birlikte değerlendirelim.</h2><p class="project-inquiry-intro">Projeniz, ihtiyaçlarınız ve tercih ettiğiniz ürün grupları hakkında bize bilgi bırakın. Ekibimiz sizinle iletişime geçsin.</p><form class="project-inquiry-form"><input required placeholder="Ad Soyad*" aria-label="Ad Soyad"><input required type="email" placeholder="E-posta Adresi*" aria-label="E-posta Adresi"><input required type="tel" placeholder="Telefon Numaranız*" aria-label="Telefon Numaranız"><select aria-label="Proje türü"><option value="">Proje türü</option><option>Konut</option><option>Otel</option><option>Ticari alan</option><option>İç mimari proje</option></select><textarea rows="4" placeholder="Projenizden kısaca bahsedin" aria-label="Proje açıklaması"></textarea><label class="project-inquiry-consent"><input required type="checkbox"> İletişim bilgilerimin proje hakkında benimle iletişime geçilmesi amacıyla kullanılmasını kabul ediyorum.</label><button class="project-inquiry-submit" type="submit">Gönder</button><p class="project-inquiry-success" hidden>Talebiniz alındı. En kısa sürede sizinle iletişime geçeceğiz.</p></form></div>';document.body.appendChild(modal);const close=()=>modal.classList.remove('is-open');modal.querySelector('.project-inquiry-close').addEventListener('click',close);modal.addEventListener('click',event=>{if(event.target===modal)close()});modal.querySelector('form').addEventListener('submit',event=>{event.preventDefault();event.currentTarget.querySelector('.project-inquiry-success').hidden=false;event.currentTarget.reset()})}modal.classList.add('is-open');modal.querySelector('input').focus()})}
function paginateBlogCards(){if(!window.__likyaHash.startsWith('#/blog'))return;const cards=[...document.querySelectorAll('.blog-grid>article')];if(!cards.length)return;const perPage=blogItemsPerPage();const pageCount=Math.ceil(cards.length/perPage);const requested=parseInt(new URLSearchParams(window.__likyaHash.split('?')[1]||'').get('page')||'1',10);const page=Math.min(Math.max(requested,1),pageCount);cards.forEach((card,index)=>card.style.display=index>=((page-1)*perPage)&&index<(page*perPage)?'':'none');document.querySelectorAll('[data-blog-page]').forEach(button=>{const target=Number(button.dataset.blogPage);button.classList.toggle('active',target===page);button.setAttribute('aria-current',target===page?'page':'false');button.onclick=()=>{window.__likyaHash='#/blog'+(target===1?'':'?page='+target)}});const next=document.querySelector('[data-blog-next]');if(next){next.disabled=page>=pageCount;next.onclick=()=>{if(page<pageCount)window.__likyaHash='#/blog?page='+(page+1)}}}
function addBlogIndexLink(){if(!window.__likyaHash.startsWith('#/blog/'))return;const article=document.querySelector('.blog-detail>article');if(!article)return;if(!article.querySelector('.blog-index-return')){const link=document.createElement('a');link.className='blog-index-return';link.href='#/blog';link.textContent='Bloga Dön';article.appendChild(link)}const sidebar=document.querySelector('.blog-sidebar');if(!sidebar||sidebar.dataset.enhanced)return;const slug=window.__likyaHash.split('/').pop();sidebar.innerHTML=`<div class="blog-contact-panel"><p class="kicker">BİZE ULAŞIN</p><h3>Projenizi birlikte değerlendirelim.</h3><p class="blog-contact-intro">Ürün, malzeme ve tasarım seçimleriniz için uzman ekibimize ulaşın.</p><form class="blog-contact-form"><label>Adınız Soyadınız<input name="ad-soyad" autocomplete="name" required></label><label>E-Posta Adresiniz<input name="eposta" type="email" autocomplete="email" required></label><label>Telefon Numaranız<input name="telefon" type="tel" autocomplete="tel"></label><label>Mesajınız<textarea name="mesaj" rows="4" required></textarea></label><button type="submit">Gönder</button><p class="form-success hidden">Teşekkür ederiz. Mesajınız başarıyla alındı.</p></form></div><div class="blog-latest-panel"><p class="kicker">SON YAZILAR</p>${blogPosts.filter(item=>item.slug!==slug).slice(0,3).map(item=>`<a class="blog-side-post" href="#/blog/${item.slug}"><img src="${I[item.image]}" alt="" loading="lazy"><span class="blog-side-copy"><small>${item.date}</small><strong>${item.title}</strong></span></a>`).join('')}</div>`;sidebar.dataset.enhanced='true';const form=sidebar.querySelector('.blog-contact-form');form.addEventListener('submit',event=>{event.preventDefault();form.querySelector('.form-success').classList.remove('hidden');form.reset()})}
function addBlogShare(){if(!window.__likyaHash.startsWith('#/blog/'))return;const article=document.querySelector('.blog-detail>article');if(!article||article.querySelector('.blog-share'))return;const title=document.querySelector('.blog-detail-hero h1')?.textContent.trim()||document.title;const pageUrl=location.href;const encodedUrl=encodeURIComponent(pageUrl);const encodedText=encodeURIComponent(title);const share=document.createElement('section');share.className='blog-share';share.setAttribute('aria-label','Blog yazısını paylaş');share.innerHTML=`<span>Paylaş</span><div class="blog-share-links"><a href="https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}" target="_blank" rel="noopener noreferrer" aria-label="Facebook'ta paylaş" title="Facebook'ta paylaş"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13.6 21v-8h2.7l.4-3.1h-3.1v-2c0-.9.3-1.5 1.6-1.5h1.7V3.6c-.3 0-1.3-.1-2.5-.1-2.5 0-4.2 1.5-4.2 4.3v2.1H7.4V13h2.8v8h3.4Z"/></svg></a><a href="https://twitter.com/intent/tweet?url=${encodedUrl}&text=${encodedText}" target="_blank" rel="noopener noreferrer" aria-label="X'te paylaş" title="X'te paylaş"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18.9 3H22l-6.8 7.8L23.2 21H17l-4.8-6.3L6.7 21H3.6l7.1-8.1L3 3h6.4l4.4 5.8L18.9 3Zm-1.1 16h1.7L8.5 4.9H6.7L17.8 19Z"/></svg></a><a href="https://www.linkedin.com/sharing/share-offsite/?url=${encodedUrl}" target="_blank" rel="noopener noreferrer" aria-label="LinkedIn'de paylaş" title="LinkedIn'de paylaş"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6.5 8.3H3.2V21h3.3V8.3ZM4.9 3A1.9 1.9 0 1 0 5 6.8 1.9 1.9 0 0 0 4.9 3ZM21 13.7c0-3.8-2-5.6-4.7-5.6-2.2 0-3.1 1.2-3.7 2V8.3H9.3V21h3.3v-6.3c0-1.7.3-3.3 2.4-3.3 2 0 2.1 1.9 2.1 3.4V21H21v-7.3Z"/></svg></a><a href="https://wa.me/?text=${encodedText}%20${encodedUrl}" target="_blank" rel="noopener noreferrer" aria-label="WhatsApp'ta paylaş" title="WhatsApp'ta paylaş"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 3.5A11.8 11.8 0 0 0 12.1 0C5.6 0 .3 5.3.3 11.8c0 2.1.5 4.1 1.6 5.9L.2 24l6.5-1.7a12 12 0 0 0 5.4 1.4h.1C18.7 23.7 24 18.4 24 11.9c0-3.2-1.2-6.2-3.5-8.4ZM12.1 21.7c-1.7 0-3.5-.5-5-1.4l-.4-.2-3.8 1 1-3.7-.2-.4a9.7 9.7 0 1 1 8.4 4.7Zm5.3-7.3c-.3-.1-1.7-.8-2-.9-.3-.1-.5-.1-.7.2l-.9 1.1c-.2.3-.5.3-.8.1-2-.9-3.3-1.7-4.6-4-.3-.6.3-.6.9-1.8.1-.2.1-.4 0-.6l-.9-2.1c-.2-.6-.5-.5-.7-.5h-.6c-.2 0-.6.1-.9.4-.3.4-1.2 1.2-1.2 2.9s1.2 3.3 1.4 3.5c.2.2 2.4 3.7 5.9 5.2.8.4 1.5.6 2 .7.8.3 1.6.2 2.2.1.7-.1 1.7-.7 1.9-1.3.2-.7.2-1.2.2-1.3-.1-.1-.3-.2-.6-.3Z"/></svg></a></div>`;const back=article.querySelector('.blog-index-return');article.insertBefore(share,back||null)}
function fixContactMapLinks(){if(!window.__likyaHash.startsWith('#/iletisim'))return;const placeUrl='https://www.google.com/maps?cid=991378877089050925';document.querySelectorAll('.map-open-link,.contact-detail[href*="google.com/maps"]').forEach(link=>{link.href=placeUrl;link.target='_blank';link.rel='noopener'});const mapFrame=document.querySelector('.showroom-map iframe');if(mapFrame){mapFrame.src='https://www.google.com/maps?q=38.4362237%2C27.1415032&z=17&output=embed';mapFrame.setAttribute('tabindex','-1');const panel=mapFrame.closest('.map-panel');if(panel&&!panel.querySelector('.map-click-overlay')){const overlay=document.createElement('a');overlay.className='map-click-overlay';overlay.href=placeUrl;overlay.target='_blank';overlay.rel='noopener';overlay.setAttribute('aria-label','Likya Yapı konumunu Google Haritalar’da açın');panel.insertBefore(overlay,mapFrame.nextSibling)}}}
function fixProfessionalShareBadge(){if(!window.__likyaHash.startsWith('#/profesyoneller'))return;const link=document.querySelector('.pro-intro>div>a');if(link){link.textContent='Projenizi Bizimle Paylaşın';link.classList.add('pro-share-badge')}}
function activeProductInquiryContext(){const parts=(window.__likyaHash||'').replace(/^#/,'').split('?')[0].split('/').filter(Boolean);if(parts[0]!=='urunler'||parts.length<3)return'';const category=products.find(item=>item.slug===parts[1]);const brand=(productCatalog[parts[1]]||[]).find(item=>item.slug===parts[2]);return category&&brand?category.name+' | '+brand.name:''}
function bindProductInquiry(){const section=document.querySelector('.product-detail-enhanced');const button=section?.querySelector('[data-product-inquiry]');if(!button)return;button.removeAttribute('href');button.setAttribute('role','button');button.setAttribute('tabindex','0');const open=()=>{let modal=document.querySelector('.product-inquiry-modal');if(!modal){modal=document.createElement('div');modal.className='project-inquiry-modal product-inquiry-modal';modal.innerHTML='<div class="project-inquiry-panel product-inquiry-panel" role="dialog" aria-modal="true" aria-label="Ürün bilgi formu"><button class="project-inquiry-close" type="button" aria-label="Formu kapat">×</button><p class="kicker">ÜRÜN BİLGİ TALEBİ</p><h2>Bizimle İletişime Geçin</h2><p class="project-inquiry-intro"><strong data-product-inquiry-name></strong> hakkında bilgi almak için formu doldurun, ekibimiz sizinle iletişime geçsin.</p><form class="project-inquiry-form product-inquiry-form"><label>Adınız Soyadınız<input name="ad-soyad" autocomplete="name" required></label><label>E-Posta Adresiniz<input name="eposta" type="email" autocomplete="email" required></label><label>Telefon Numaranız<input name="telefon" type="tel" autocomplete="tel"></label><label>Konu<input name="konu" data-product-subject required></label><label>Mesajınız<textarea name="mesaj" rows="4" required></textarea></label><button class="project-inquiry-submit" type="submit">Mesaj Gönder</button><p class="project-inquiry-success" hidden>Teşekkür ederiz. Mesajınız başarıyla alındı.</p></form></div>';document.body.appendChild(modal);const close=()=>modal.classList.remove('is-open');modal.querySelector('.project-inquiry-close').addEventListener('click',close);modal.addEventListener('click',event=>{if(event.target===modal)close()});modal.querySelector('form').addEventListener('submit',event=>{event.preventDefault();event.currentTarget.querySelector('.project-inquiry-success').hidden=false;event.currentTarget.reset()})}const context=activeProductInquiryContext();if(!context)return;const subject=context+' hakkında bilgi talebi';modal.querySelector('[data-product-inquiry-name]').textContent=context;const subjectInput=modal.querySelector('[data-product-subject]');subjectInput.value=subject;subjectInput.defaultValue=subject;subjectInput.setAttribute('value',subject);subjectInput.dataset.i18nOriginalValue=subject;modal.querySelector('.project-inquiry-success').hidden=true;modal.classList.add('is-open');modal.querySelector('input').focus()};button.addEventListener('click',open);button.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open()}})}
function bindCatalogueFilters(){if(!window.__likyaHash.startsWith('#/kataloglar'))return;const buttons=[...document.querySelectorAll('[data-catalogue-filter]')];const cards=[...document.querySelectorAll('[data-catalogue-category]')];const title=document.querySelector('[data-catalogue-title]');const count=document.querySelector('[data-catalogue-count]');buttons.forEach(button=>button.addEventListener('click',()=>{const selected=button.dataset.catalogueFilter;let visible=0;buttons.forEach(item=>{const active=item===button;item.classList.toggle('selected',active);item.setAttribute('aria-pressed',active?'true':'false')});cards.forEach(card=>{const show=selected==='Tüm Kataloglar'||card.dataset.catalogueCategory===selected;card.hidden=!show;if(show)visible++});if(title)title.textContent=selected;if(count)count.textContent=visible+' katalog'}))}
function refineCatalogueCopy(){if(!window.__likyaHash.startsWith('#/kataloglar'))return;const catalogueHero=document.querySelector('.hero.inner-hero');const heroText=document.querySelector('.hero-copy>p');const introText=document.querySelector('.catalogue-intro>p');const sourceNote=document.querySelector('.catalogue-source-note');if(catalogueHero)catalogueHero.classList.add('catalogue-hero');if(heroText)heroText.textContent='Seçkin markaların kataloglarını tek bir arşivde keşfedin.';if(introText)introText.textContent='Kategorilere göz atın, ilginizi çeken markaların güncel katalog ve koleksiyonlarına kolayca ulaşın.';if(sourceNote)sourceNote.remove()}
function separateInquiryModals(){document.querySelectorAll('.product-inquiry-modal.project-inquiry-modal').forEach(modal=>modal.classList.remove('project-inquiry-modal'))}
function enforceNumericPhoneInputs(){document.querySelectorAll('input[type="tel"],input[name="telefon"]').forEach(input=>{input.inputMode='numeric';input.pattern='[0-9]*';if(input.dataset.numericPhoneReady)return;input.dataset.numericPhoneReady='true';input.addEventListener('input',()=>{const digits=input.value.replace(/\D/g,'');if(input.value!==digits)input.value=digits})})}
const previousRender=render;render=function(){previousRender();separateInquiryModals();addProjectMeta();bindProjectInquiry();bindProductInquiry();bindCatalogueFilters();refineCatalogueCopy();paginateBlogCards();addBlogIndexLink();addBlogShare();fixContactMapLinks();fixProfessionalShareBadge();enforceNumericPhoneInputs()};addEventListener('hashchange',render);document.addEventListener('input',event=>{const input=event.target;if(input instanceof HTMLInputElement&&(input.type==='tel'||input.name==='telefon')){const digits=input.value.replace(/\D/g,'');if(input.value!==digits)input.value=digits}});render();
