<script id="address-line-definitive-fix">
(function(){
  function fixAddress(){
    if(!window.__likyaHash.startsWith('#/iletisim'))return;
    const address=document.querySelector('.contact-details-grid [data-contact-kind="address"] .contact-item-copy span');
    if(address)address.textContent='Cumhuriyet Bulvar\u0131 No:212/A, Alsancak / \u0130zmir';
  }
  let queued=false;function run(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;fixAddress()})}
  document.addEventListener('DOMContentLoaded',run);window.addEventListener('hashchange',()=>setTimeout(run,0));
  new MutationObserver(run).observe(document.documentElement,{childList:true,subtree:true});run();
})();
