    'AKALIN İNŞAAT BOSTANLI (KARŞIYAKA)',
    'AKALIN İNŞAAT GİRNE (KARŞIYAKA)',
    'VİLLA NOVA PROJESİ (BORNOVA)',
    'YEL DEĞİRMENLERİ PROJESİ (GÜZELBAHÇE)',
    'ASMA BAHEÇELER (NARLIDERE)',
    'MAVİ SU EVLERİ (NARLIDERE)',
    'GÜNVAR İNŞAAT HILL KONUTLARI (BAYRAKLI)',
    'VARYANT 35 PROJESİ (KARŞIYAKA)',
    'NAYMAN SUITES PAŞALİMANI (ÇEŞME)',
    'SÜRMELİ HOTELS& RESORT (KUŞADASI)',
    'LİBERTY HOTELS&LYKİA (FETHİYE)',
    'OTEL LYKİA WORLD (FETHİYE)',
    'AYPARK PROJESİ (KARŞIYAKA)',
    'YAŞAM EVLERİ (BORNOVA)',
    'LAİLA KONAKLARI (GÜZELBAHÇE)',
    'SELENOVA EVLERİ (BORNOVA)',
    'GÖZEGİR OTEL (BODRUM)',
    'BRYELA PROJESİ (URLA)',
    'RICHMOUND EPHESUS RESORT (KUŞADASI)',
    'N LATIİS PROJESİ (NARLIDERE)',
    'EMSA İNŞAAT (İZMİR)',
    'SWİSS OTEL BÜYÜK EFES (KONAK)',
    'KONAK OTEL',
    'STÜDYO 35 (KARŞIYAKA)',
    'ROYAL ASARLIK BEACH (BODRUM)',
    'MAGIC LIFE (BODRUM)',
    'GEMAK YAPI PREMIUM EVLERİ (ÇEŞME)',
    'GERGÜL İNŞAAT MODERN 1-2-3-4 PROJELERİ (MAVİŞEHİR)',
    'MİCOSTA VE MİKORA VİLLALARI (ÇEŞME)',
    'SAKİN EV HOTEL (ÇEŞME)',
    'KEY HOTEL (KONAK)',
    'SÜRMELİ OTEL (İSTANBUL)',
    'ENGİN OTEL (GAZİEMİR)',
    'DASİF İNŞAAT (İZMİR)',
    'CARİSHMA OTEL',
    'HİLTON KUŞADASI',
    'SEA AMORA SEALİGHT OTEL',
    'RAMADA KUŞADASI',
    'RİCOSTA OTEL RİZE',
    'LİBERT HOTEL (FETHİYE)',
    'İSTİNYE PARK (İZMİR)',
    'MARRİOT HOTEL (İZMİR)',
    'RİCOSTA OTEL (RİZE)',
    'ATILGAN SUİTS (MAVİŞEHİR)',
    'ENANTİK OTEL (ALSANCAK)',
    'PORT MARİN (İZMİR)',
    'EKMAS MAVİŞEHİR',
    'HYATT REGENCY (İZMİR)',
    'LUVİ URLA',
    'FOLKART BOYALIK BEACH (ÇEŞME)',
    'MAGNESİA (AYDIN)',
    'İSTİNYE PARK (İSTANBUL)',
    'SWISSOTEL (ÇEŞME)'
  ];

  function key(value) {
    return String(value)
      .toLocaleUpperCase('tr-TR')
      .replace(/[İIıi]/g, 'I')
      .replace(/[^A-ZÇĞİÖŞÜ0-9]+/g, '')
      .trim();
  }

  function baseKey(value) {
    return key(String(value).replace(/\([^)]*\)/g, ''));
  }

  function buildReferenceList() {
    const result = initialReferences.slice();
    const initialKeys = initialReferences.map(key);
    const used = new Set(initialKeys);
    sourceReferences.forEach(function (reference) {
      const referenceKey = key(reference);
      const referenceBaseKey = baseKey(reference);
      const alreadyRepresented = initialKeys.some(function (initialKey) {
        return referenceBaseKey === initialKey || referenceBaseKey.startsWith(initialKey);
      });
      if (!referenceKey || alreadyRepresented || used.has(referenceKey)) return;
      used.add(referenceKey);
      result.push(reference);
    });
    return result;
  }

  const allReferences = buildReferenceList();

  function buttonLabel(expanded) {
    return document.documentElement.lang === 'en'
      ? (expanded ? 'Show Less' : 'View All')
      : (expanded ? 'Daha Az Göster' : 'Tümünü Gör');
  }

  function enhanceOtherReferences() {
    const section = document.querySelector('.references-index-section');
    const list = section && section.querySelector('.other-refs');
    const heading = section && section.querySelector('.other-title');
    if (!section || !list || !heading || list.dataset.otherRefsEnhanced === 'true') return;

    list.dataset.otherRefsEnhanced = 'true';
    list.id = 'other-references-list';
    list.classList.add('other-refs-enhanced');
    heading.classList.add('other-refs-heading-enhanced');

    list.replaceChildren(...allReferences.map(function (reference, index) {
      const item = document.createElement('div');
      item.className = 'other-ref-item';
      item.style.borderBottom = '1px solid var(--line)';
      item.style.padding = '14px 0';
      item.textContent = reference;
      item.hidden = index >= 8;
      return item;
    }));

    const row = document.createElement('div');
    row.className = 'other-refs-toggle-row';
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'other-refs-toggle';
    button.setAttribute('aria-controls', list.id);
    button.setAttribute('aria-expanded', 'false');
    button.textContent = buttonLabel(false);
    row.appendChild(button);
    list.insertAdjacentElement('afterend', row);

    button.addEventListener('click', function () {
      const expanded = button.getAttribute('aria-expanded') === 'true';
      const nextExpanded = !expanded;
      [...list.children].forEach(function (item, index) { item.hidden = !nextExpanded && index >= 8; });
      button.setAttribute('aria-expanded', String(nextExpanded));
      button.textContent = buttonLabel(nextExpanded);
      if (!nextExpanded) heading.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  }

  document.addEventListener('DOMContentLoaded', enhanceOtherReferences);
  window.addEventListener('hashchange', function () { setTimeout(enhanceOtherReferences, 0); });
  new MutationObserver(enhanceOtherReferences).observe(document.documentElement, { childList: true, subtree: true });
  new MutationObserver(function () {
    const button = document.querySelector('.references-index-section .other-refs-toggle');
    if (button) button.textContent = buttonLabel(button.getAttribute('aria-expanded') === 'true');
  }).observe(document.documentElement, { attributes: true, attributeFilter: ['lang'] });
  enhanceOtherReferences();
})();
</script>
