<script id="reference-functional-summary-carousel-behaviour">
(function(){
  const projectDecisions={
    'folkart-towers':{
      need:'Yüksek katlı konutlarda güçlü mimari kimliği günlük kullanım konforuyla dengelemek.',
      solution:'Doğal taş etkili yüzeyleri sıcak ahşap dokular ve yalın banyo ekipmanlarıyla eşleştirmek.',
      result:'Ortak alanlardan banyolara kadar devam eden sakin, bütüncül ve zamansız bir mekân dili.'
    },
    'marriott-hotel':{
      need:'Yoğun misafir kullanımında prestijli görünümü, dayanıklılığı ve kolay bakımı birlikte sağlamak.',
      solution:'Otel banyolarında işlevsel depolama, karakterli armatür ve dirençli yüzeyleri bir araya getirmek.',
      result:'Konuk deneyimini destekleyen, uzun ömürlü ve tutarlı bir iç mekân standardı.'
    },
    'hyatt-regency':{
      need:'Farklı kullanım yoğunluklarına sahip otel alanlarında çağdaş ve tutarlı bir kimlik kurmak.',
      solution:'Yalın mobilya, dengeli armatür geometrisi ve kesintisiz drenaj çözümlerini birlikte değerlendirmek.',
      result:'Estetik kararlarla kullanım rahatlığının birbirini tamamladığı rafine konaklama alanları.'
    },
    'swissotel':{
      need:'Spa ve konaklama alanlarında dinlenme hissini güçlendiren konforlu bir atmosfer oluşturmak.',
      solution:'Doğal tonları sauna, wellness ve duş çözümleriyle sakin bir malzeme paletinde buluşturmak.',
      result:'Islak hacimlerle dinlenme alanları arasında kesintisiz ve huzurlu bir deneyim.'
    },
    'istinyepark':{
      need:'Yoğun ziyaretçi trafiğinde dikkat çekici görünümü ve yüksek kullanım dayanımını korumak.',
      solution:'Güçlü yüzeyleri modern armatürler ve işlevsel tamamlayıcılarla dengeli biçimde kurgulamak.',
      result:'Ticari mekânın dinamizmine uyum sağlayan seçkin, okunaklı ve uzun ömürlü alanlar.'
    },
    'radisson-blu-resort-spa':{
      need:'Tatil ve spa deneyimini hem konforlu hem de karakterli bir malzeme diliyle desteklemek.',
      solution:'Wellness teknolojisini zamansız armatürler ve dokulu mozaik yüzeylerle bir araya getirmek.',
      result:'Deniz atmosferini iç mekânda sürdüren rahat, duyusal ve bütüncül kullanım alanları.'
    },
    'ramada-encore-izmir':{
      need:'Kompakt şehir oteli banyolarında alanı verimli kullanırken konfordan ödün vermemek.',
      solution:'Bütüncül mobilya, hijyenik vitrifiye ve ince formlu ısıtma çözümlerini birlikte planlamak.',
      result:'Bakımı kolay, çağdaş ve misafir kullanımına uygun dengeli banyo alanları.'
    },
    'doubletree-by-hilton-sarnic':{
      need:'Otelin güven veren kimliğini oda ve ortak alanlarda dayanıklı çözümlerle sürdürmek.',
      solution:'Modüler vitrifiye, karakterli seramik yüzey ve şeffaf duş çözümlerini aynı dilde birleştirmek.',
      result:'İlk kullanımdan uzun dönem işletmeye kadar konfor ve dayanıklılık sunan mekânlar.'
    },
    'boyalik-beach-hotel-spa':{
      need:'Sahil ferahlığını spa, banyo ve dinlenme alanlarında sürdürülebilir kılmak.',
      solution:'Suya dayanıklı ürünleri doğal malzemeler ve dekoratif odaklarla dengeli biçimde eşleştirmek.',
      result:'Zamansız görünümü koruyan, rahat ve bütünlüklü bir kıyı oteli deneyimi.'
    }
  };
  function buildSummary(detail,slug){
    const copy=detail.querySelector(':scope>div:first-child');
    const oldPanel=copy?.querySelector('.reference-project-story');
    const meta=copy?.querySelector('.reference-project-meta');
    if(!copy||!oldPanel||oldPanel.classList.contains('is-functional-summary'))return;
    const values=[...meta?.querySelectorAll(':scope>div')||[]].map(item=>({
      label:item.querySelector('span')?.textContent||'',value:item.querySelector('b')?.textContent||''
    }));
    const type=values.find(item=>item.label.includes('TÜRÜ'))?.value||'Referans projesi';
    const location=values.find(item=>item.label.includes('LOKASYON'))?.value||'İzmir';
    const content=projectDecisions[slug]||{
      need:'Mimari kimlik ile kullanım ihtiyaçlarını aynı proje standardında buluşturmak.',
      solution:'Ürün, yüzey ve uygulama kararlarını mekânın ölçeğine göre birlikte değerlendirmek.',
      result:'Estetik, dayanıklı ve uzun süre değerini koruyan bütüncül kullanım alanları.'
    };
    oldPanel.className='reference-project-story is-functional-summary';
    oldPanel.innerHTML='<div class="reference-functional-head"><div><p class="kicker">PROJE ÖZETİ</p><h3>Karardan sonuca</h3></div><div class="reference-functional-facts"><span class="reference-functional-fact"><span>PROJE</span><b>'+type+'</b></span><span class="reference-functional-fact"><span>KONUM</span><b>'+location+'</b></span></div></div><div class="reference-functional-list"><div class="reference-functional-item"><span class="reference-functional-number">01</span><span class="reference-functional-label">İHTİYAÇ</span><p>'+content.need+'</p></div><div class="reference-functional-item"><span class="reference-functional-number">02</span><span class="reference-functional-label">ÇÖZÜM</span><p>'+content.solution+'</p></div><div class="reference-functional-item"><span class="reference-functional-number">03</span><span class="reference-functional-label">KAZANIM</span><p>'+content.result+'</p></div></div>';
  }
  function buildCarousel(detail){
    const section=detail.querySelector('.product-gallery .reference-used-products.is-gallery-integrated');
    const head=section?.querySelector('.reference-used-products-head');
    const track=section?.querySelector('.reference-used-products-grid');
    if(!section||!head||!track||section.dataset.carouselReady)return;
    section.dataset.carouselReady='true';
    const kicker=head.querySelector('.kicker');
    const title=head.querySelector('h3');
    const wrap=document.createElement('div');wrap.className='reference-products-title-wrap';
    if(kicker)wrap.appendChild(kicker);if(title)wrap.appendChild(title);head.prepend(wrap);
    const tools=document.createElement('div');tools.className='reference-product-carousel-tools';
    const cards=[...track.querySelectorAll('.reference-used-product')];
    tools.innerHTML='<span class="reference-product-carousel-count">'+cards.length+' ürün</span><button class="reference-product-carousel-button" type="button" data-reference-product-prev aria-label="Önceki ürün">←</button><button class="reference-product-carousel-button" type="button" data-reference-product-next aria-label="Sonraki ürün">→</button>';
    head.appendChild(tools);
    const prev=tools.querySelector('[data-reference-product-prev]');
    const next=tools.querySelector('[data-reference-product-next]');
    const move=direction=>{const card=track.querySelector('.reference-used-product');const gap=parseFloat(getComputedStyle(track).columnGap)||8;track.scrollBy({left:direction*((card?.getBoundingClientRect().width||track.clientWidth)+gap),behavior:'smooth'})};
    const update=()=>{const max=Math.max(0,track.scrollWidth-track.clientWidth-2);const staticTrack=max<=2;tools.classList.toggle('is-static',staticTrack);prev.disabled=track.scrollLeft<=2;next.disabled=track.scrollLeft>=max};
    prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));track.addEventListener('scroll',update,{passive:true});
    if('ResizeObserver' in window)new ResizeObserver(update).observe(track);window.addEventListener('resize',update);requestAnimationFrame(update);
  }
  function enhance(){
    const match=window.__likyaHash.match(/^#\/referanslar\/([^/?]+)/);if(!match)return;
    const detail=document.querySelector('.reference-detail-enhanced');if(!detail)return;
    buildSummary(detail,match[1]);buildCarousel(detail);
  }
  let queued=false;function run(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;enhance()})}
  document.addEventListener('DOMContentLoaded',run);window.addEventListener('hashchange',()=>setTimeout(run,0));
  new MutationObserver(run).observe(document.documentElement,{childList:true,subtree:true});run();
})();
</script>
