<script id="reference-story-balance-behaviour">
(function(){
  const stories={
    'folkart-towers':'Doğal taşın güçlü karakteri, sıcak ahşap dokularla dengelenerek yüksek katlı yaşam alanlarına zamansız ve sakin bir atmosfer kazandırıldı.',
    'marriott-hotel':'Yoğun kullanıma uygun yüzeyler ile rafine banyo detayları bir araya getirilerek konuk deneyimini destekleyen kalıcı bir tasarım dili oluşturuldu.',
    'hyatt-regency':'Yalın geometriler, konforlu kullanım ve çağdaş yüzey kararları aynı çizgide buluşturularak otel kimliği bütüncül biçimde ele alındı.',
    'swissotel':'Spa ve dinlenme alanlarında doğal tonlar, dokunsal yüzeyler ve konfor odaklı ürünler sakin bir deneyim oluşturacak biçimde eşleştirildi.',
    'istinyepark':'Yüksek ziyaretçi trafiğine cevap veren dayanıklı malzemeler, güçlü yüzey geçişleri ve rafine detaylarla ticari mekânın dinamizmi dengelendi.',
    'radisson-blu-resort-spa':'Deniz ve tatil atmosferini destekleyen doğal dokular, wellness çözümleri ve zamansız armatür seçimleri ortak bir tasarım dili içinde kurgulandı.',
    'ramada-encore-izmir':'Kompakt alanlarda verimli kullanım, kolay bakım ve sıcak malzeme etkisi bir araya getirilerek çağdaş şehir otelciliğine uygun çözümler üretildi.',
    'doubletree-by-hilton-sarnic':'İlk izlenimi güçlendiren yüzey kararları ile dayanıklı ve konforlu banyo çözümleri, markanın güven veren konaklama yaklaşımıyla eşleştirildi.',
    'boyalik-beach-hotel-spa':'Sahil atmosferinin ferahlığı; suya dayanıklı yüzeyler, doğal malzemeler ve konforlu wellness ürünleriyle iç mekâna taşındı.'
  };
  function enhance(){
    const match=window.__likyaHash.match(/^#\/referanslar\/([^/?]+)/);if(!match)return;
    const detail=document.querySelector('.reference-detail-enhanced');
    const copy=detail?.querySelector(':scope>div:first-child');
    const actions=copy?.querySelector(':scope>.detail-actions');
    const products=detail?.querySelector('.product-gallery .reference-used-products');
    if(!detail||!copy||!actions||!products||copy.querySelector('.reference-project-story'))return;
    const brands=[...products.querySelectorAll('.reference-used-product-brand')]
      .map(node=>(node.textContent||'').split('·')[0].trim()).filter(Boolean);
    const unique=[...new Set(brands)];
    const panel=document.createElement('section');
    panel.className='reference-project-story';
    panel.setAttribute('aria-label','Projenin tasarım yaklaşımı ve tercih edilen markalar');
    panel.innerHTML='<div class="reference-project-story-head"><div><p class="kicker">PROJE YAKLAŞIMI</p><h3>Mekâna yön veren seçimler</h3></div><span class="reference-project-story-index">0'+Math.min(unique.length,9)+'</span></div><p class="reference-project-story-text">'+(stories[match[1]]||'Mimari karakter, kullanım ihtiyaçları ve malzeme seçimleri aynı bütün içinde değerlendirilerek projeye özgü, dengeli bir mekân dili oluşturuldu.')+'</p><div class="reference-project-brands"><span class="reference-project-brands-label">Tercih edilen markalar</span>'+unique.map(brand=>'<span class="reference-project-brand">'+brand+'</span>').join('')+'</div>';
    copy.insertBefore(panel,actions);
  }
  let queued=false;function run(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;enhance()})}
  document.addEventListener('DOMContentLoaded',run);
  window.addEventListener('hashchange',()=>setTimeout(run,0));
  new MutationObserver(run).observe(document.documentElement,{childList:true,subtree:true});
  run();
})();
</script>
