<script>
(()=>{
  const visualAssets=[
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,'
  ];
  const heroByRoute={
    '/urunler':visualAssets[0],
    '/hakkimizda':visualAssets[2],
    '/referanslar':visualAssets[3],
    '/profesyoneller':visualAssets[4],
    '/kataloglar':visualAssets[6],
    '/blog':visualAssets[7],
    '/iletisim':visualAssets[2]
  };
  function routePath(){return(window.__likyaHash.slice(1)||'/').split('?')[0]}
  function routeVisualIndex(value){let total=0;for(let index=0;index<value.length;index++)total=(total*31+value.charCodeAt(index))>>>0;return total%visualAssets.length}
  function setBackground(element,source,dark=.58){if(element)element.style.backgroundImage=`linear-gradient(90deg,rgba(15,12,10,${dark}),rgba(15,12,10,.10)),url("${source}")`}
  function refreshVisuals(){
    const path=routePath();
    requestAnimationFrame(()=>{
      if(path==='/'){
        const homeSlides=[...document.querySelectorAll('.home-hero-slide')];
        if(homeSlides.length<4){setTimeout(refreshVisuals,80);return;}
        [visualAssets[0],visualAssets[1],visualAssets[2],visualAssets[3]].forEach((source,index)=>setBackground(homeSlides[index],source,.42));
      }else{
        let heroSource=heroByRoute[path];
        if(!heroSource&&path.startsWith('/urunler/'))heroSource=path.split('/').length>4?visualAssets[5]:visualAssets[6];
        if(!heroSource&&path.startsWith('/referanslar/'))heroSource=visualAssets[3];
        if(!heroSource&&path.startsWith('/blog/'))heroSource=visualAssets[7];
        setBackground(document.querySelector('.hero.inner-hero'),heroSource||visualAssets[2]);
        setBackground(document.querySelector('.blog-hero,.blog-detail-hero'),heroSource||visualAssets[7],.72);
      }
      const homeGroups=path==='/'?document.querySelector('[data-home-product-groups]'):null;
      const backgroundCards=homeGroups?.homeProductCards||[...document.querySelectorAll('.image-card,.product-card')];
      backgroundCards.forEach((card,index)=>setBackground(card,visualAssets[index%visualAssets.length],.38));
      const completeVisuals=visualAssets.slice(0,4);
      const referenceCards=[...document.querySelectorAll('.reference-grid>a')];
      referenceCards.forEach((card,index)=>{
        const images=card.querySelectorAll('.reference-card-image');
        const primarySource=completeVisuals[index%completeVisuals.length];
        const hoverSource=completeVisuals[(index+1)%completeVisuals.length];
        images.forEach((image,imageIndex)=>{
          image.src=imageIndex===0?primarySource:hoverSource;
          image.style.backgroundImage='none';
          image.loading=index>2?'lazy':'eager';
        });
      });
      const relatedProductThumbs=[...document.querySelectorAll('.related-product-thumb')];
      relatedProductThumbs.forEach((thumb,index)=>setBackground(thumb,completeVisuals[index%completeVisuals.length],.12));
      const blogSideImages=[...document.querySelectorAll('.blog-side-post img')];
      blogSideImages.forEach((image,index)=>{image.src=completeVisuals[index%completeVisuals.length];image.loading='lazy'});
      const contentImages=[...document.querySelectorAll('.intro>img,.showroom>img,.project-grid img,.wide-image,.pro-intro img,.detail-gallery img,.product-gallery img,.blog-card-image img,.blog-detail-image,.showroom-map>img,.brands-story-image')];
      contentImages.forEach((image,index)=>{
        image.src=visualAssets[(index+2)%visualAssets.length];
        image.loading=index>2?'lazy':'eager';
      });
      const productCtaImage=document.querySelector('.cta img');
      if(productCtaImage&&path.startsWith('/urunler')){
        const visualIndex=routeVisualIndex(path);
        productCtaImage.src=visualAssets[visualIndex];
        productCtaImage.style.objectPosition=['center','center 38%','center 62%','left center','right center'][visualIndex%5];
        productCtaImage.alt='Seçili ürün grubuna uygun mimari uygulama görseli';
      }
      const pageCtaVisuals={
        '/hakkimizda':visualAssets[0],
        '/referanslar':visualAssets[2],
        '/profesyoneller':visualAssets[6],
        '/blog':visualAssets[4]
      };
      if(productCtaImage&&!path.startsWith('/urunler')){
        let pageCtaSource=pageCtaVisuals[path];
        if(path.startsWith('/referanslar/'))pageCtaSource=visualAssets[1];
        if(path.startsWith('/blog/'))pageCtaSource=visualAssets[5];
        if(pageCtaSource){
          productCtaImage.src=pageCtaSource;
          productCtaImage.style.objectPosition='center';
          productCtaImage.alt='Sayfa içeriğine uygun mimari uygulama görseli';
        }
      }
    });
  }
  refreshVisuals();
  addEventListener('hashchange',refreshVisuals);
  const app=document.getElementById('app');if(app)new MutationObserver(refreshVisuals).observe(app,{childList:true});
})();
</script>
