<script>
(()=>{
  const mapUrl='https://www.google.com/maps?cid=991378877089050925';
  const pinterestPath='M12 2a10 10 0 0 0-3.64 19.31c-.09-1.68-.02-3.68.42-5.56l1.29-5.46s-.32-.65-.32-1.61c0-1.51.87-2.64 1.96-2.64.93 0 1.38.7 1.38 1.53 0 .93-.59 2.32-.9 3.61-.26 1.08.54 1.96 1.61 1.96 1.93 0 3.41-2.04 3.41-4.97 0-2.6-1.87-4.42-4.54-4.42-3.09 0-4.91 2.32-4.91 4.72 0 .93.36 1.94.81 2.48.09.11.1.2.07.31l-.3 1.23c-.05.2-.16.24-.37.15-1.38-.64-2.24-2.66-2.24-4.28 0-3.48 2.53-6.68 7.29-6.68 3.83 0 6.8 2.73 6.8 6.37 0 3.8-2.4 6.86-5.72 6.86-1.12 0-2.17-.58-2.53-1.27l-.69 2.62c-.25.96-.92 2.16-1.37 2.89A10 10 0 1 0 12 2Z';
  function enhanceFooter(){
    const footer=document.querySelector('.footer');
    if(!footer)return;
    const address=[...footer.querySelectorAll('.footer-contact-item')].find(item=>item.textContent.includes('Cumhuriyet Bulvarı'));
    if(address&&address.tagName!=='A'){
      const link=document.createElement('a');
      link.className=address.className+' footer-address-link';
      link.href=mapUrl;
      link.target='_blank';
      link.rel='noopener noreferrer';
      link.setAttribute('aria-label',"Likya Yapı adresini Google Haritalar'da aç");
      link.innerHTML=address.innerHTML.replace('<p>','<span>').replace('</p>','</span>');
      address.replaceWith(link);
    }
    const pinterest=footer.querySelector('.socials a[aria-label="Pinterest"]');
    if(pinterest&&!pinterest.querySelector('.pinterest-modern-icon')){
      pinterest.innerHTML=`<svg class="pinterest-modern-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${pinterestPath}"></path></svg>`;
    }
  }
  enhanceFooter();
  const app=document.getElementById('app');
  if(app)new MutationObserver(enhanceFooter).observe(app,{childList:true});
})();
</script>
