<script>
(()=>{const initialized=new WeakSet();function enhanceProductGalleries(){document.querySelectorAll('[data-product-gallery]').forEach(gallery=>{if(initialized.has(gallery))return;initialized.add(gallery);const stage=gallery.querySelector('[data-gallery-stage]'),main=gallery.querySelector('[data-gallery-main]'),lens=gallery.querySelector('[data-gallery-lens]'),zoom=gallery.querySelector('[data-gallery-zoom]'),prev=gallery.querySelector('[data-gallery-prev]'),next=gallery.querySelector('[data-gallery-next]'),thumbs=[...gallery.querySelectorAll('[data-gallery-image]')];if(!stage||!main||!lens||!zoom||!thumbs.length)return;let current=Math.max(0,thumbs.findIndex(thumb=>thumb.classList.contains('active')));const select=index=>{current=(index+thumbs.length)%thumbs.length;const thumb=thumbs[current],source=I[thumb.dataset.galleryImage];main.src=source;zoom.style.backgroundImage=`url("${source}")`;thumbs.forEach((item,itemIndex)=>{const active=itemIndex===current;item.classList.toggle('active',active);item.setAttribute('aria-pressed',active?'true':'false')});gallery.classList.remove('is-zooming')};select(current);thumbs.forEach((thumb,index)=>thumb.addEventListener('click',()=>select(index)));prev&&prev.addEventListener('click',event=>{event.stopPropagation();select(current-1)});next&&next.addEventListener('click',event=>{event.stopPropagation();select(current+1)});stage.addEventListener('mousemove',event=>{if(window.matchMedia('(hover:none)').matches||innerWidth<=850||event.target.closest('.product-gallery-nav')){gallery.classList.remove('is-zooming');return}const box=stage.getBoundingClientRect(),lensWidth=lens.offsetWidth,lensHeight=lens.offsetHeight,x=Math.max(0,Math.min(event.clientX-box.left,box.width)),y=Math.max(0,Math.min(event.clientY-box.top,box.height));lens.style.left=`${Math.max(0,Math.min(x-lensWidth/2,box.width-lensWidth))}px`;lens.style.top=`${Math.max(0,Math.min(y-lensHeight/2,box.height-lensHeight))}px`;zoom.style.backgroundPosition=`${x/box.width*100}% ${y/box.height*100}%`;gallery.classList.add('is-zooming')});stage.addEventListener('mouseleave',()=>gallery.classList.remove('is-zooming'))})}enhanceProductGalleries();new MutationObserver(enhanceProductGalleries).observe(document.getElementById('app'),{childList:true})})();
</script>
