.project-inquiry-modal{position:fixed;inset:0;z-index:100;background:rgba(25,21,19,.68);display:flex;align-items:center;justify-content:center;padding:24px;opacity:0;visibility:hidden;transition:opacity .2s ease,visibility .2s ease}
.project-inquiry-modal.is-open{opacity:1;visibility:visible}
.project-inquiry-panel{position:relative;width:min(560px,100%);max-height:min(720px,calc(100vh - 48px));overflow:auto;background:#f4eee9;color:var(--ink);padding:38px 42px 42px;box-shadow:0 24px 80px rgba(0,0,0,.25)}
.project-inquiry-panel h2{font-size:clamp(30px,4vw,44px);line-height:1.08;margin:8px 0 12px}
.project-inquiry-intro{font-size:13px;line-height:1.6;color:#62564f;margin:0 0 24px;max-width:450px}
.project-inquiry-close{position:absolute;top:12px;right:18px;border:0;background:none;color:#806f64;font-size:38px;font-weight:300;line-height:1;cursor:pointer}
.project-inquiry-form{display:grid;gap:12px}.project-inquiry-form input:not([type=checkbox]),.project-inquiry-form select,.project-inquiry-form textarea{width:100%;border:1px solid rgba(128,111,100,.28);background:rgba(255,255,255,.55);padding:14px 15px;color:var(--ink);outline:none}.project-inquiry-form input:not([type=checkbox]):focus,.project-inquiry-form select:focus,.project-inquiry-form textarea:focus{border-color:var(--accent)}.project-inquiry-form textarea{resize:vertical}.project-inquiry-consent{display:flex;gap:9px;align-items:flex-start;color:#665b54;font-size:11px;line-height:1.45;margin:3px 0}.project-inquiry-consent input{margin-top:2px;accent-color:var(--accent)}.project-inquiry-submit{border:0;background:#171716;color:#fff;padding:15px 24px;font-size:12px;font-weight:600;cursor:pointer}.project-inquiry-submit:hover{background:#80634f}.project-inquiry-success{color:#526348;border-top:1px solid #9aaa8e;padding-top:12px;font-size:12px;margin:0}
@media(max-width:560px){.project-inquiry-panel{padding:34px 22px 26px}.project-inquiry-panel h2{font-size:32px}.project-inquiry-modal{padding:14px}}

/* Referans kartları: fareyle üzerine gelince ikinci proje görseline geçiş */
.references-index-section .reference-card{
  position:relative;
  isolation:isolate;
  overflow:hidden;
  background:none!important;
  filter:none!important;
}
.references-index-section .reference-card-media,
.references-index-section .reference-card-shade{
  position:absolute;
  inset:0;
  display:block;
  width:100%;
  height:100%;
  margin:0!important;
}
.references-index-section .reference-card-media{z-index:-2;background:#2b2724}
.references-index-section .reference-card-shade{
  z-index:-1;
  background:linear-gradient(0deg,rgba(12,10,9,.72) 0%,rgba(12,10,9,.2) 52%,rgba(12,10,9,.04) 100%);
  pointer-events:none;
}
.references-index-section .reference-card-image{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  max-width:none;
  object-fit:cover;
  object-position:center;
  transition:opacity .5s cubic-bezier(.22,.61,.36,1),transform .75s cubic-bezier(.22,.61,.36,1);
}
.references-index-section .reference-card-image-primary{opacity:1;transform:scale(1)}
.references-index-section .reference-card-image-hover{opacity:0;transform:scale(1.035)}
.references-index-section .reference-card:hover .reference-card-image-primary,
.references-index-section .reference-card:focus-visible .reference-card-image-primary{opacity:0;transform:scale(1.025)}
.references-index-section .reference-card:hover .reference-card-image-hover,
.references-index-section .reference-card:focus-visible .reference-card-image-hover{opacity:1;transform:scale(1)}
.references-index-section .reference-card>div{position:relative;z-index:1}
@media(hover:none){
  .references-index-section .reference-card-image-primary{opacity:1!important;transform:none!important}
  .references-index-section .reference-card-image-hover{opacity:0!important;transform:none!important}
}
@media(prefers-reduced-motion:reduce){.references-index-section .reference-card-image{transition:none}}

/* Blog detayları: Likya'nın sakin, editoryal tasarımına uygun okuma ritmi */
.blog-detail{--leading-body:1.5}
.blog-detail article{max-width:780px}
.blog-detail article>p{
  line-height:var(--leading-body)!important;
  margin:0 0 22px;
}
.blog-detail .blog-lead{
  font-size:27px!important;
  line-height:1.42!important;
  margin:0 0 38px!important;
}
.blog-detail article h2{
  font-size:34px!important;
  line-height:1.2!important;
  letter-spacing:-.025em;
  margin:44px 0 16px!important;
}
.blog-detail article h2:first-of-type{margin-top:38px!important}
.blog-detail blockquote{margin:38px 0!important}
@media(max-width:700px){
  .blog-detail article{max-width:none}
  .blog-detail .blog-lead{font-size:22px!important;line-height:1.4!important;margin-bottom:30px!important}
  .blog-detail article h2{font-size:28px!important;margin:34px 0 14px!important}
}

/* Blog detay kapağı: iç sayfalarla orantılı, daha kompakt başlık alanı */
.blog-detail .blog-detail-image{display:none!important}
.blog-detail-hero{
  min-height:460px!important;
  background-position:center!important;
  background-size:cover!important;
}
.blog-detail-hero>div{
  max-width:900px;
  padding:126px max(8vw,30px) 48px!important;
}
.blog-detail-hero .blog-meta{
  margin-top:0!important;
  margin-bottom:14px!important;
}
.blog-detail-hero h1{
  max-width:760px;
  font-size:clamp(40px,4vw,56px)!important;
  line-height:1.06!important;
}
@media(max-width:850px){
  .blog-detail-hero{min-height:430px!important}
  .blog-detail-hero>div{padding:112px 24px 42px!important}
  .blog-detail-hero h1{font-size:clamp(36px,6vw,48px)!important}
}
