.blog-detail .blog-index-return{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  margin-top:16px;
  padding:10px 18px;
  border:1px solid rgba(33,29,26,.48);
  border-radius:999px;
  color:var(--ink);
  font-size:12px;
  font-weight:500;
  line-height:1.2;
  transition:background .2s ease,color .2s ease,border-color .2s ease;
}
.blog-detail .blog-index-return:hover,
.blog-detail .blog-index-return:focus-visible{
  background:var(--ink);
  border-color:var(--ink);
  color:#fff;
}
.blog-sidebar{gap:28px}
.blog-sidebar>div.blog-contact-panel,
.blog-sidebar>div.blog-latest-panel{padding:28px;background:rgba(255,255,255,.28);border:1px solid rgba(128,111,100,.25)}
.blog-contact-panel h3{font-family:var(--font-site);font-size:27px;line-height:1.12;margin:8px 0 10px}
.blog-contact-intro{margin:0 0 22px;color:#665950;line-height:1.55}
.blog-contact-panel h3,
.blog-contact-panel .blog-contact-intro{display:none}
.blog-contact-panel>.kicker{margin-bottom:20px}
.blog-contact-form{display:grid;gap:15px}
.blog-contact-form label{display:grid;gap:6px;font-size:10px;letter-spacing:.02em;color:#74675f}
.blog-contact-form input,
.blog-contact-form textarea{width:100%;box-sizing:border-box;border:1px solid rgba(128,111,100,.32);border-radius:6px;background:rgba(255,255,255,.34);padding:11px 12px;color:var(--ink);font:13px/1.4 var(--font-site);outline:none;resize:vertical;transition:border-color .2s,background .2s}
.blog-contact-form input:focus,
.blog-contact-form textarea:focus{border-color:var(--accent);background:rgba(255,255,255,.55)}
.blog-contact-form button{justify-self:start;border:1px solid var(--ink);border-radius:999px;background:var(--ink);color:#fff;padding:10px 20px;font:600 12px/1.2 var(--font-site);cursor:pointer;transition:background .2s,color .2s}
.blog-contact-form button:hover,
.blog-contact-form button:focus-visible{background:transparent;color:var(--ink)}
.blog-contact-form .form-success{margin:0;color:#655347;font-size:11px;line-height:1.45}
.blog-latest-panel>.kicker{margin-bottom:18px}
.blog-sidebar .blog-side-post{display:flex!important;align-items:center;gap:14px;padding:12px 0;border:0;font-family:var(--font-site)}
.blog-sidebar .blog-side-post+.blog-side-post{border-top:1px solid rgba(128,111,100,.22)}
.blog-side-post img{width:82px;height:62px;flex:0 0 82px;object-fit:cover}
.blog-sidebar .blog-side-post .blog-side-copy{display:flex!important;flex:1 1 auto;min-width:0;margin:0!important;flex-direction:column;align-items:flex-start;gap:7px;font-family:var(--font-site)}
.blog-sidebar .blog-side-copy small{display:block;width:100%;margin:0;font:9px/1.2 var(--font-site);letter-spacing:.04em;color:#86766c}
.blog-sidebar .blog-side-copy strong{display:block;width:100%;margin:0;font:500 13px/1.32 var(--font-site);color:var(--ink);overflow-wrap:break-word}
@media(max-width:1000px){.blog-sidebar>div.blog-contact-panel,.blog-sidebar>div.blog-latest-panel{padding:26px}}
@media(max-width:650px){.blog-sidebar{grid-template-columns:1fr}.blog-side-post img{width:92px;height:68px;flex-basis:92px}}
