/* Modern contact form fields */
.contact .contact-form{gap:22px}
.contact .contact-form label{display:grid;gap:8px;font-size:11px;color:#665950}
.contact .contact-form input,
.contact .contact-form select,
.contact .contact-form textarea{
  width:100%;
  box-sizing:border-box;
  border:1px solid rgba(128,111,100,.28);
  border-radius:8px;
  background:rgba(255,255,255,.34);
  color:var(--ink);
  padding:12px 14px;
  font:13px/1.45 var(--font-site);
  outline:none;
  transition:border-color .2s ease,background .2s ease,box-shadow .2s ease;
}
.contact .contact-form input,
.contact .contact-form select{min-height:46px}
.contact .contact-form textarea{min-height:138px;resize:vertical}
.contact .contact-form input:focus,
.contact .contact-form select:focus,
.contact .contact-form textarea:focus{
  border-color:var(--accent);
  background:rgba(255,255,255,.58);
  box-shadow:0 0 0 3px rgba(157,121,92,.10);
}
.contact .contact-form input::placeholder,
.contact .contact-form textarea::placeholder{color:#91847b;opacity:1}
.contact .contact-form button{
  border:1px solid var(--ink);
  border-radius:999px;
  padding:12px 24px;
  transition:background .2s ease,color .2s ease,transform .2s ease;
}
.contact .contact-form button:hover,
.contact .contact-form button:focus-visible{background:transparent;color:var(--ink);transform:translateY(-1px)}
.professional-form .form-grid{column-gap:24px;row-gap:20px}
