/* Showroom: larger map, compact title area */
.showroom-map>img{height:430px}
.showroom-map .map-panel{height:430px;grid-template-rows:minmax(0,1fr) auto}
.showroom-map .map-panel>div{padding:18px 5vw 20px}
.showroom-map .map-panel .kicker{margin:0 0 7px}
.showroom-map .map-panel h2{font:400 clamp(28px,2.5vw,38px)/1.05 var(--font-site);margin:0}
.showroom-map .map-panel iframe{grid-row:1;grid-column:1;pointer-events:none}
.showroom-map .map-panel>div{grid-row:2;grid-column:1}
.map-click-overlay{grid-row:1;grid-column:1;display:block;z-index:2;cursor:pointer;border:0!important;padding:0!important}
.map-click-overlay:focus-visible{outline:2px solid var(--accent);outline-offset:-3px}
.pro-intro .pro-share-badge{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:max-content;
  margin-top:18px;
  padding:10px 18px;
  border:1px solid rgba(33,29,26,.48);
  border-radius:999px;
  color:var(--ink);
  font:600 12px/1.2 var(--font-site);
  transition:background .2s ease,color .2s ease,border-color .2s ease;
}
.pro-intro .pro-share-badge:hover,
.pro-intro .pro-share-badge:focus-visible{background:var(--ink);border-color:var(--ink);color:#fff;outline:none}
.product-inquiry-modal{position:fixed;inset:0;z-index:100;background:rgba(25,21,19,.68);display:flex;align-items:center;justify-content:center;padding:24px;opacity:0;visibility:hidden;transition:opacity .2s ease,visibility .2s ease}
.product-inquiry-modal.is-open{opacity:1;visibility:visible}
.product-inquiry-panel{width:min(560px,100%);max-height:min(720px,calc(100vh - 48px));padding:34px 38px 38px}
.product-inquiry-panel h2{font-family:var(--font-site);font-size:clamp(30px,3.2vw,40px);margin:7px 0 10px}
.product-inquiry-panel .project-inquiry-intro{margin-bottom:20px;color:#665950}
.product-inquiry-panel .project-inquiry-intro strong{font-weight:600;color:var(--ink)}
.product-inquiry-form{gap:14px}
.product-inquiry-form label{display:grid;gap:6px;color:#6f625a;font:500 10px/1.3 var(--font-site)}
.product-inquiry-form input:not([type=checkbox]),
.product-inquiry-form textarea{border-radius:8px;background:rgba(255,255,255,.42);padding:11px 13px;font:13px/1.4 var(--font-site)}
.product-inquiry-form input:not([type=checkbox]){min-height:42px}
.product-inquiry-form textarea{min-height:100px}
.product-inquiry-form input:focus,
.product-inquiry-form textarea:focus{box-shadow:0 0 0 3px rgba(157,121,92,.10)}
.product-inquiry-form .project-inquiry-submit{justify-self:start;border:1px solid var(--ink);border-radius:999px;padding:11px 22px}
.product-inquiry-form .project-inquiry-submit:hover{background:transparent;color:var(--ink)}
.blog-share{display:flex;align-items:center;gap:16px;margin:34px 0 18px;padding:18px 20px;border:1px solid rgba(128,111,100,.28);border-radius:12px;background:rgba(255,255,255,.22)}
.blog-share>span{color:#6f625a;font:600 11px/1 var(--font-site);letter-spacing:.14em;text-transform:uppercase}
.blog-share-links{display:flex;align-items:center;gap:9px}
.blog-share-links a{display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;border:1px solid rgba(33,29,26,.28);border-radius:50%;color:var(--ink);transition:background .2s ease,color .2s ease,border-color .2s ease,transform .2s ease}
.blog-share-links a:hover,.blog-share-links a:focus-visible{background:var(--ink);border-color:var(--ink);color:#fff;transform:translateY(-2px);outline:none}
.blog-share-links svg{width:17px;height:17px;fill:currentColor}
@media(max-width:560px){.product-inquiry-modal{padding:14px}.product-inquiry-panel{padding:30px 22px 24px}.product-inquiry-form{gap:12px}}
@media(max-width:560px){.blog-share{justify-content:space-between;gap:10px;padding:15px 16px}.blog-share-links{gap:7px}.blog-share-links a{width:36px;height:36px}}
@media(max-width:850px){
  .showroom-map>img{height:320px}
  .showroom-map .map-panel{height:390px}
