/* Katalog arşivi */
.catalogue-archive{padding-top:74px;padding-bottom:96px}
.catalogue-intro{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(300px,.75fr);gap:8vw;align-items:end;margin-bottom:62px}
.catalogue-intro h2{max-width:680px;font-size:clamp(34px,3.25vw,48px)!important;line-height:1.08!important}
.catalogue-intro>p{max-width:590px;margin:0;color:#62574f;font-size:15px}
.catalogue-layout{display:grid;grid-template-columns:255px minmax(0,1fr);gap:56px;align-items:start}
.catalogue-filters{position:sticky;top:24px;border-top:1px solid rgba(33,29,26,.68)}
.catalogue-filter-heading,.catalogue-filters button{width:100%;display:flex;align-items:center;justify-content:space-between;gap:16px;border:0;border-bottom:1px solid rgba(128,111,100,.28);background:transparent;color:#6f645d;padding:18px 6px;text-align:left;cursor:pointer}
.catalogue-filter-heading{color:var(--ink);cursor:default;font-weight:600}
.catalogue-filter-heading small,.catalogue-filters button small{color:#968a82;font-size:10px;font-weight:500}
.catalogue-filters button span{font-size:12px;line-height:1.35}
.catalogue-filters button.selected{padding-left:16px;background:rgba(255,255,255,.34);color:var(--ink);box-shadow:inset 3px 0 0 var(--accent)}
.catalogue-filters button:hover,.catalogue-filters button:focus-visible{color:var(--ink);background:rgba(255,255,255,.22);outline:none}
.catalogue-results-head{display:flex;align-items:end;justify-content:space-between;gap:20px;padding-bottom:20px;margin-bottom:28px;border-bottom:1px solid rgba(33,29,26,.68)}
.catalogue-results-head .kicker{margin:0 0 7px}
.catalogue-results-head h3{font:400 clamp(26px,2.5vw,38px)/1.1 var(--font-site)}
.catalogue-results-head>span{color:#887970;font-size:11px}
.catalogue-card-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:40px 18px}
.catalogue-card[hidden]{display:none!important}
.catalogue-cover{position:relative;display:block;aspect-ratio:4/5;overflow:hidden;background:#262321;color:#fff}
.catalogue-cover:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(18,15,13,.08),rgba(18,15,13,.16) 44%,rgba(18,15,13,.86));transition:background .3s ease}
.catalogue-cover>img{width:100%;height:100%;object-fit:cover;filter:saturate(.72) contrast(.96);transition:transform .55s ease,filter .3s ease}
.catalogue-cover>span{position:absolute;z-index:2;right:14px;top:14px;padding:7px 10px;border-radius:999px;background:rgba(24,21,19,.82);font-size:8px;font-weight:600;letter-spacing:.12em}
.catalogue-cover>div{position:absolute;z-index:2;left:20px;right:20px;bottom:20px}
.catalogue-cover>div small{display:block;margin-bottom:8px;font-size:9px;letter-spacing:.18em;color:#d2b89f}
.catalogue-cover>div strong{display:block;font:400 clamp(21px,2vw,30px)/1.08 var(--font-site)}
.catalogue-cover:hover>img,.catalogue-cover:focus-visible>img{transform:scale(1.045);filter:saturate(.9) contrast(1)}
.catalogue-cover:hover:after,.catalogue-cover:focus-visible:after{background:linear-gradient(180deg,rgba(18,15,13,.03),rgba(18,15,13,.1) 40%,rgba(18,15,13,.75))}
.catalogue-cover:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.catalogue-card-copy{padding-top:15px}
.catalogue-card-copy>p{margin:0 0 5px;color:#92765f;font-size:9px;font-weight:600;letter-spacing:.16em}
.catalogue-card-copy h4{min-height:32px;margin:0 0 5px;font:500 18px/1.28 var(--font-site)}
.catalogue-card-copy>div{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-bottom:13px;border-bottom:1px solid rgba(128,111,100,.28)}
