<style>
/* Ana sayfa kapak görseli slider yapısı. */
.hero.home-slider-ready{background-image:none!important;overflow:hidden}
.home-hero-slide{position:absolute;inset:0;background-position:center;background-size:cover;opacity:0;transition:opacity .9s ease;z-index:0}
.home-hero-slide.is-active{opacity:1}
.hero.home-slider-ready::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(15,12,10,.82),rgba(15,12,10,.08));z-index:1;pointer-events:none}
.hero.home-slider-ready>.header,.hero.home-slider-ready>.hero-copy{z-index:3}
.home-slider-dots{position:absolute;left:50%;bottom:22px;z-index:4;display:flex;gap:9px;transform:translateX(-50%)}
.home-slider-dot{width:8px;height:8px;padding:0;border:1px solid #fff;border-radius:50%;background:transparent;cursor:pointer}
.home-slider-dot.is-active{background:#fff}
@media(max-width:560px){.home-slider-dots{bottom:15px}}
</style>
<script>
(()=>{
  const slideNames=['home-hero-v2.png','showroom-v2.png','project-v2.png','spa-v2.png'];
  function initHomeSlider(){
    if((window.__likyaHash.slice(1)||'/').split('?')[0]!=='/')return;
    const hero=document.querySelector('.hero:not(.inner-hero)');
    if(!hero||hero.dataset.sliderReady)return;
    hero.dataset.sliderReady='true';
    hero.classList.add('home-slider-ready');
    const fitToViewport=()=>{
      hero.style.setProperty('height',`${window.innerHeight}px`,'important');
      hero.style.setProperty('min-height',`${window.innerHeight}px`,'important');
      hero.style.setProperty('width',`${document.documentElement.clientWidth}px`,'important');
      hero.style.setProperty('max-width','none','important');
    };
    fitToViewport();
    window.addEventListener('resize',fitToViewport,{passive:true});
    window.addEventListener('orientationchange',fitToViewport,{passive:true});
    const layers=slideNames.map((name,index)=>{
      const layer=document.createElement('div');
      layer.className='home-hero-slide'+(index===0?' is-active':'');
      layer.style.backgroundImage=`url("${I[name]}")`;
      hero.prepend(layer);
      return layer;
    });
    const dots=document.createElement('div');dots.className='home-slider-dots';
    let current=0,timer;
    const buttons=layers.map((_,index)=>{const button=document.createElement('button');button.type='button';button.className='home-slider-dot'+(index===0?' is-active':'');button.setAttribute('aria-label',`${index+1}. g\u00f6rsel`);button.addEventListener('click',()=>show(index,true));dots.appendChild(button);return button});
    function show(index,restart=false){current=(index+layers.length)%layers.length;layers.forEach((layer,i)=>layer.classList.toggle('is-active',i===current));buttons.forEach((button,i)=>button.classList.toggle('is-active',i===current));if(restart)start()}
    function start(){clearInterval(timer);timer=setInterval(()=>{if(!hero.isConnected){clearInterval(timer);return}show(current+1)},5000)}
    hero.append(dots);start();
  }
  initHomeSlider();
  const app=document.getElementById('app');if(app)new MutationObserver(initHomeSlider).observe(app,{childList:true});
})();
</script>
