<script>
(()=>{
  function enforceBlogCleanup(){
    const heading=document.querySelector('.blog-index .blog-heading');
    if(heading)heading.style.setProperty('border-bottom','none','important');
    document.querySelectorAll('.blog-index .blog-card-image > span').forEach(number=>number.remove());
    document.querySelectorAll('.blog-detail article > p').forEach(paragraph=>paragraph.style.setProperty('line-height','1.3','important'));
  }
  enforceBlogCleanup();
  addEventListener('hashchange',()=>requestAnimationFrame(enforceBlogCleanup));
  const app=document.getElementById('app');
  if(app)new MutationObserver(enforceBlogCleanup).observe(app,{childList:true,subtree:true});
})();
</script>
