.form-consent-box input[type="checkbox"]{appearance:auto!important;-webkit-appearance:checkbox!important;flex:0 0 auto!important;width:15px!important;height:15px!important;min-height:0!important;margin:1px 0 0!important;padding:0!important;border:initial!important;border-radius:2px!important;accent-color:var(--accent)}
