<script id="contact-showroom-consent-behaviour">
(function(){
  const consentText='İletişim bilgilerimin talebim hakkında benimle iletişime geçilmesi amacıyla kullanılmasını kabul ediyorum.';
  function enhanceContactDetails(root){
    const area=root.querySelector('.contact>div:first-child');
    if(!area||area.querySelector('.contact-details-grid'))return;
    const links=[...area.querySelectorAll(':scope > a.contact-detail')];if(!links.length)return;
    const intro=document.createElement('p');intro.className='contact-details-intro';intro.textContent='Sorularınız, ürün seçimleriniz ve projeleriniz için ekibimize doğrudan ulaşabilirsiniz.';
    const grid=document.createElement('div');grid.className='contact-details-grid';
    links.forEach((link,index)=>{link.dataset.contactKind=index===0?'phone':index===1?'email':'address';grid.appendChild(link)});
    const heading=area.querySelector('h2');heading.insertAdjacentElement('afterend',intro);intro.insertAdjacentElement('afterend',grid);
  }
  function addConsent(form){
    if(!form||form.querySelector('.form-consent-box'))return;
    const button=form.querySelector('button[type="submit"],.project-inquiry-submit');if(!button)return;
    const label=document.createElement('label');label.className='form-consent-box';label.innerHTML='<input type="checkbox" name="iletisim-onayi" required><span>'+consentText+'</span>';
    button.insertAdjacentElement('beforebegin',label);
  }
  function enhance(){
    enhanceContactDetails(document);
    document.querySelectorAll('[data-contact-panel="general"] form,[data-contact-panel="professional"] form,.product-inquiry-form,.blog-contact-form').forEach(addConsent);
  }
  let scheduled=false;function schedule(){if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;enhance()})}
  document.addEventListener('DOMContentLoaded',schedule);window.addEventListener('hashchange',()=>setTimeout(schedule,0));
  new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true});schedule();
})();
</script>
