<script id="contact-emergency-final-behaviour">
(function(){
  const clockSvg='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"></circle><path d="M12 7v5l3 2"></path></svg>';
  function finishContact(){
    if(!window.__likyaHash.startsWith('#/iletisim'))return;
    const grid=document.querySelector('.contact-details-grid');
    if(grid&&!grid.querySelector('[data-contact-kind="hours"]')){
      const hours=document.createElement('div');hours.className='contact-detail';hours.dataset.contactKind='hours';
      hours.innerHTML='<span class="contact-icon" aria-hidden="true">'+clockSvg+'</span><span class="contact-item-copy"><b>Çalışma Saatleri</b><span>Pazartesi – Cuma / 09:00 – 18:00</span></span>';
      grid.appendChild(hours);
    }
    const left=document.querySelector('.contact>div:first-child');
    if(left&&!left.querySelector('.contact-showroom-image')){
      const source=document.querySelector('.showroom-map>img');
      if(source){const image=source.cloneNode();image.className='contact-showroom-image';image.alt='Likya Yapı showroom iç mekânı';left.appendChild(image)}
    }
  }
  let queued=false;function run(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;finishContact()})}
  document.addEventListener('DOMContentLoaded',run);window.addEventListener('hashchange',()=>setTimeout(run,0));
  new MutationObserver(run).observe(document.documentElement,{childList:true,subtree:true});run();
})();
</script>
