<script id="phone-direct-dial-final">
(function(){
  const dialUrl='tel:+902324639994';
  function activatePhone(){
    if(!window.__likyaHash.startsWith('#/iletisim'))return;
    const phone=document.querySelector('.contact-details-grid [data-contact-kind="phone"]');
    if(!phone)return;
    phone.href=dialUrl;phone.removeAttribute('role');phone.removeAttribute('tabindex');
    phone.setAttribute('aria-label','Likya Yapı telefon numarasını arayın');
    if(phone.dataset.directDialBound)return;
    phone.dataset.directDialBound='true';
    phone.addEventListener('click',function(event){event.preventDefault();window.location.href=dialUrl});
    phone.addEventListener('keydown',function(event){if(event.key==='Enter'){event.preventDefault();window.location.href=dialUrl}});
  }
  let queued=false;function run(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;activatePhone()})}
  document.addEventListener('DOMContentLoaded',run);window.addEventListener('hashchange',()=>setTimeout(run,0));new MutationObserver(run).observe(document.documentElement,{childList:true,subtree:true});run();
})();
</script>
