<script id="phone-link-lock-final">
(function(){
  const dialUrl='tel:+902324639994';
  function isPhone(item){return item?.querySelector('.contact-item-copy b')?.textContent.trim().toLocaleLowerCase('tr-TR')==='telefon'}
  function lock(){
    if(!window.__likyaHash.startsWith('#/iletisim'))return;
    document.querySelectorAll('.contact-details-grid .contact-detail').forEach(item=>{
      if(!isPhone(item))return;
      if(item.getAttribute('href')!==dialUrl)item.setAttribute('href',dialUrl);
      item.removeAttribute('target');item.removeAttribute('rel');item.removeAttribute('role');item.dataset.contactKind='phone';
      item.onclick=function(event){event.preventDefault();event.stopImmediatePropagation();window.location.href=dialUrl};
    });
  }
  let queued=false;function run(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;lock()})}
  const observer=new MutationObserver(run);
  document.addEventListener('DOMContentLoaded',()=>{observer.observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['href']});run()});
  window.addEventListener('hashchange',()=>setTimeout(run,0));run();
})();
</script>
