    ]
  };
  function render(){
    const match=window.__likyaHash.match(/^#\/referanslar\/([^/?]+)/);if(!match)return;
    const products=projectProducts[match[1]];const detail=document.querySelector('.reference-detail-enhanced');
    if(!products||!detail||document.querySelector('.reference-used-products'))return;
    const section=document.createElement('section');section.className='section reference-used-products';
    section.innerHTML='<div class="reference-used-products-head"><div><p class="kicker">PROJEDE KULLANILAN ÜRÜNLER</p><h2>Projeye Değer Katan Seçimler</h2></div><p>Bu projede tercih edilen ürün ve koleksiyonları inceleyin; teknik özellikler ve benzer seçenekler için ürün detay sayfalarına ulaşın.</p></div><div class="reference-used-products-grid">'+products.map((item,index)=>'<a class="reference-used-product" href="'+item.href+'"><span class="reference-used-product-number">'+String(index+1).padStart(2,'0')+'</span><p class="reference-used-product-brand">'+item.brand+' · '+item.type+'</p><h3>'+item.name+'</h3><p class="reference-used-product-description">'+item.description+'</p></a>').join('')+'</div>';
    detail.insertAdjacentElement('afterend',section);
  }
  let queued=false;function run(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;render()})}
  document.addEventListener('DOMContentLoaded',run);window.addEventListener('hashchange',()=>setTimeout(run,0));new MutationObserver(run).observe(document.documentElement,{childList:true,subtree:true});run();
})();
</script>
