<script id="reference-used-products-integrated-behaviour">
(function(){
  function integrate(){
    if(!window.__likyaHash.startsWith('#/referanslar/'))return;
    const detail=document.querySelector('.reference-detail-enhanced');
    const section=document.querySelector('.reference-used-products');
    const actions=detail?.querySelector('.detail-actions');
    if(!detail||!section||!actions||section.classList.contains('is-compact'))return;
    const items=[...section.querySelectorAll('.reference-used-product')].map(card=>({
      href:card.getAttribute('href'),brand:card.querySelector('.reference-used-product-brand')?.textContent||'',name:card.querySelector('h3')?.textContent||''
    }));
    if(!items.length)return;
    section.classList.add('is-compact');
    section.innerHTML='<div class="reference-used-products-head"><p class="kicker">PROJEDE KULLANILAN ÜRÜNLER</p><h3>Malzeme ve Ürün Seçimleri</h3></div><div class="reference-used-products-grid">'+items.map(item=>'<a class="reference-used-product" href="'+item.href+'"><span class="reference-used-product-main"><span class="reference-used-product-brand">'+item.brand+'</span><h3>'+item.name+'</h3></span></a>').join('')+'</div>';
    actions.insertAdjacentElement('beforebegin',section);
  }
  let queued=false;function run(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;integrate()})}
  document.addEventListener('DOMContentLoaded',run);window.addEventListener('hashchange',()=>setTimeout(run,0));new MutationObserver(run).observe(document.documentElement,{childList:true,subtree:true});run();
})();
</script>







