  function addExtraProducts(track, slug) {
    if (track.dataset.refreshExtrasAdded === slug) return;
    track.dataset.refreshExtrasAdded = slug;
    const items = extraProducts[slug] || [];
    items.forEach(function (item) {
      if (track.querySelector('[href="' + item.href + '"]')) return;
      const card = document.createElement('a');
      const number = String(track.querySelectorAll('.reference-used-product').length + 1).padStart(2, '0');
      card.className = 'reference-used-product reference-refresh-added-product';
      card.href = item.href;
      card.innerHTML =
        '<span class="reference-used-product-main">' +
          '<span class="reference-used-product-brand">' + item.brand + ' · ' + item.type + '</span>' +
          '<h3>' + item.name + '</h3>' +
        '</span>';
      track.appendChild(card);
    });
  }

  function placeInOriginalColumn(copy, products) {
    const oldShowcase = products.closest('.reference-product-showcase');
    const actions = copy.querySelector(':scope > .detail-actions');
    if (products.parentElement !== copy) copy.insertBefore(products, actions || null);
    products.classList.add('is-refresh-slider');
    if (oldShowcase && oldShowcase.isConnected) oldShowcase.remove();
  }

  function productIcon(type) {
    const value = (type || '').toLocaleLowerCase('tr-TR');
    if (value.includes('armatür') || value.includes('batarya')) {
      return '<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M14 42h34M22 42V29c0-8 5-13 13-13h8v9H34c-2 0-3 1-3 4v13M43 20h7M47 25v8M18 47v4M44 47v4"/></svg>';
