    if (value.includes('seramik') || value.includes('mozaik') || value.includes('yüzey')) {
      return '<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M13 13h38v38H13zM13 31h38M31 13v38M16 26l10-10M35 48l13-13"/></svg>';
    }
    if (value.includes('dolap') || value.includes('mobilya')) {
      return '<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M12 25h40v24H12zM17 19h30v6M28 36h8M18 49v4M46 49v4M22 19c0-5 4-8 10-8s10 3 10 8"/></svg>';
    }
    return '<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M18 12h28v40H18zM23 17h18v21H23zM27 45h10M43 28h4"/></svg>';
