  function productCover(href) {
    try {
      const parts = (href || '').replace(/^#/, '').split('?')[0].split('/').filter(Boolean);
      const category = products.find(function (item) { return item.slug === parts[1]; });
      const brand = (productCatalog[parts[1]] || []).find(function (item) { return item.slug === parts[2]; });
      return imageSource(brand?.images?.[0] || category?.image || '');
    } catch (error) {
      return '';
    }
  }

  function buildSlider(products) {
    const track = products.querySelector('.reference-used-products-grid');
    const cards = [...products.querySelectorAll('.reference-used-product')];
    if (!track || cards.length === 0) return;
    let head = products.querySelector('.reference-used-products-head');
    if (!head) {
      head = document.createElement('div');
      head.className = 'reference-used-products-head';
      products.prepend(head);
    }
    if (!head.classList.contains('is-refresh-head')) {
      head.className = 'reference-used-products-head is-refresh-head';
      head.innerHTML =
        '<div class="reference-refresh-heading"><p class="kicker">PROJEDE KULLANILAN ÜRÜNLER</p>' +
        '<h3>Malzeme &amp; ürün seçkisi</h3><p>Detay sayfalarına doğrudan ulaşın</p></div>' +
        '<div class="reference-refresh-controls"><span class="reference-refresh-status" aria-live="polite"></span>' +
