      thumb.className = 'reference-product-thumb';
      thumb.innerHTML = cover ? '<img src="' + cover + '" alt="">' : productIcon(type);
      card.prepend(thumb);
    });
    let viewport = track.parentElement;
    if (!viewport.classList.contains('reference-products-viewport')) {
      viewport = document.createElement('div');
      viewport.className = 'reference-products-viewport';
      track.parentNode.insertBefore(viewport, track);
      viewport.appendChild(track);
    }
    if (products.dataset.refreshSliderReady === 'true') return;
    products.dataset.refreshSliderReady = 'true';
    const prev = head.querySelector('[data-refresh-prev]');
    const next = head.querySelector('[data-refresh-next]');
    const status = head.querySelector('.reference-refresh-status');
    let page = 0;
    function pageSize() {
      const width = window.innerWidth;
      return width <= 560 ? 1 : width <= 1100 ? 3 : 2;
    }
    function update() {
      const size = pageSize();
      const pageCount = Math.max(1, Math.ceil(cards.length / size));
      page = Math.min(page, pageCount - 1);
      const start = page * size;
      const visible = Math.min(size, cards.length - start);
      const end = Math.min(cards.length, start + visible);
      track.style.setProperty('grid-template-columns', 'repeat(' + Math.max(1, visible) + ', minmax(0, 1fr))', 'important');
      cards.forEach(function (card, cardIndex) {
        const shown = cardIndex >= start && cardIndex < end;
        card.classList.toggle('is-page-visible', shown);
        card.style.removeProperty('flex');
        card.style.setProperty('display', shown ? 'flex' : 'none', 'important');
        card.style.setProperty('width', shown ? 'auto' : '100%', 'important');
        card.setAttribute('aria-hidden', shown ? 'false' : 'true');
        card.tabIndex = shown ? 0 : -1;
      });
      track.style.transform = 'none';
      status.textContent = (start + 1) + '–' + end + ' / ' + cards.length;
      prev.disabled = page <= 0;
      next.disabled = page >= pageCount - 1;
    }
    prev.addEventListener('click', function () { page = Math.max(0, page - 1); update(); });
    next.addEventListener('click', function () { page += 1; update(); });
    window.addEventListener('resize', update);
    if ('ResizeObserver' in window) new ResizeObserver(update).observe(viewport);
    requestAnimationFrame(update);
  }

  function refresh() {
    const homeLink = document.querySelector('.hero:not(.inner-hero) .hero-link');
    if (homeLink) {
      homeLink.textContent = 'Koleksiyonları Keşfedin';
      homeLink.classList.add('home-cta-refined');
    }
    const match = window.__likyaHash.match(/^#\/referanslar\/([^/?]+)/);
    if (!match) return;
    const detail = document.querySelector('.reference-detail-enhanced');
    const copy = detail?.querySelector(':scope > div:first-child');
    const gallery = detail?.querySelector(':scope > .product-gallery');
    const products = detail?.querySelector('.reference-used-products') || document.querySelector('.reference-product-showcase .reference-used-products');
    if (!detail || !copy || !gallery || !products) return;
    detail.classList.add('reference-layout-refresh');
    copy.classList.add('reference-editorial-copy');
    const track = products.querySelector('.reference-used-products-grid');
    if (!track) return;
    addExtraProducts(track, match[1]);
    placeInOriginalColumn(copy, products);
    buildSlider(products);
  }

  let queued = false;
  function run() {
    if (queued) return;
    queued = true;
    requestAnimationFrame(function () { queued = false; refresh(); });
  }
  document.addEventListener('DOMContentLoaded', run);
  window.addEventListener('hashchange', function () { setTimeout(run, 0); });
  new MutationObserver(run).observe(document.documentElement, { childList: true, subtree: true });
  run();
})();
</script>
