  filter: saturate(1) contrast(1.02) !important;
}

.catalogue-card-expanded .catalogue-card-copy h4 {
  min-height: 2.25em;
  text-wrap: balance;
}

.catalogue-card-expanded .catalogue-card-copy > div > a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
}

.catalogue-card-expanded .catalogue-card-copy > div > a > span {
  display: inline-grid;
  place-items: center;
  line-height: 1;
}

/* Kartlar eşit yükseklikte olsun, alt satır (kategori + link) hep aynı hizada dursun */
.catalogue-card-expanded {
  display: flex;
  flex-direction: column;
}

.catalogue-card-expanded .catalogue-card-copy {
  display: flex;
  flex: 1;
  flex-direction: column;
}

.catalogue-card-expanded .catalogue-card-copy > div {
  margin-top: auto;
}

/* Kart başlığı ve "Kataloğu İncele": Poppins, daha hafif ve yumuşak koyu ton */
.catalogue-card-expanded .catalogue-card-copy h4 {
  font-family: "Poppins", Arial, sans-serif !important;
  font-weight: 500 !important;
  color: #3f3833 !important;
}

.catalogue-card-expanded .catalogue-card-copy > div > a {
  font-family: "Poppins", Arial, sans-serif !important;
  font-weight: 500 !important;
  color: #4a423c !important;
}

.catalogue-card-expanded .catalogue-card-copy > div > a:hover,
.catalogue-card-expanded .catalogue-card-copy > div > a:focus-visible {
  color: var(--accent) !important;
}

/* Laptop / masaüstü: yan yana 4 katalog */
@media (min-width: 1200px) {
  .catalogue-card-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
  }
}

/* Dar laptop (1024 dahil): yan yana 3 katalog */
@media (min-width: 900px) and (max-width: 1199px) {
  .catalogue-card-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  }
}

/* Tablet (dikey) ve mobil: yan yana 2 katalog */
@media (max-width: 899px) {
  .catalogue-card-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }
}

@media (max-width: 560px) {
  .catalogue-card-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    gap: 28px 12px !important;
  }

  .catalogue-card-expanded .catalogue-cover {
    aspect-ratio: 4 / 5 !important;
  }

  .catalogue-card-expanded .catalogue-card-copy {
    padding-top: 12px;
  }

  .catalogue-card-expanded .catalogue-card-copy > p {
    margin-bottom: 4px;
    font-size: 8px;
    letter-spacing: .1em;
  }

  .catalogue-card-expanded .catalogue-card-copy h4 {
    min-height: 2.6em;
    margin-bottom: 8px;
    font-size: 14px;
    line-height: 1.28;
  }

  /* Kategori yazısı ve buton aynı satırda, dikeyde aynı hizada */
  .catalogue-card-expanded .catalogue-card-copy > div {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    gap: 6px;
    padding-bottom: 10px;
  }

  .catalogue-card-expanded .catalogue-card-copy > div > span {
    min-width: 0;
    font-size: 9px;
  }

  .catalogue-card-expanded .catalogue-card-copy > div > a {
    flex: 0 0 auto;
    gap: 4px;
    font-size: 10px;
  }
}

/* /assets/katalog içinden gelen gerçek marka kapakları: renk filtresi uygulanmasın */
.catalogue-cover-clean > img.has-brand-cover,
.catalogue-cover-clean:hover > img.has-brand-cover,
.catalogue-cover-clean:focus-visible > img.has-brand-cover {
  filter: none !important;
}
</style><script data-bundle="likya-catalogue-expanded">(function () {
  'use strict';

  const sources = {
    'LAUFEN': 'https://www.laufen.co.uk/products/downloads',
    'Glass Design': 'https://www.glassdesign.it/en/',
    'Iris Ceramica': 'https://www.irisceramica.com/download-catalogues',
    'Fiandre': 'https://www.fiandre.com/downloads/',
    'Ceramica Cielo': 'https://www.ceramicacielo.it/en/download/cataloghi',
    'CEA Design': 'https://www.ceadesign.it/en/news/2-catalogues',
    'Emilgroup': 'https://www.emilgroup.com/downloadarea/',
    'Emilceramica': 'https://www.emilgroup.com/downloadarea/',
    'Ergon': 'https://www.emilgroup.com/downloadarea/',
    'Provenza': 'https://www.emilgroup.com/downloadarea/',
    'Viva': 'https://www.emilgroup.com/downloadarea/',
    'Level': 'https://www.emilgroup.com/downloadarea/'
  };

  // Katalog kapak dosya adı: marka + katalog adı (ör. laufen-sonar, keuco-royal-modular-2-0)
  function slugify(value) {
    return String(value)
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .replace(/\+/g, ' plus ')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
  }

  const catalogues = [
    ['LAUFEN','LUA & LANI','Vitrifiye ve Banyo','/assets/katalog/laufen-lua-lani.jpg'],
    ['LAUFEN','Solutions','Banyo Çözümleri','/assets/katalog/laufen-solutions.jpg'],
    ['Glass Design','Percorsi Privilegiati Dell’Acqua','Lavabolar','/assets/katalog/glass-design-percorsi-privilegiati-dell-acqua.jpg'],
    ['Glass Design','Glamorous Tuning','Bataryalar','/assets/katalog/glass-design-glamorous-tuning.jpg'],
    ['Iris Ceramica','General Catalogue','Seramik ve yüzeyler','/assets/katalog/iris-ceramica-general-catalogue.jpg'],
    ['Iris Ceramica','AVISTA','Seramik ve yüzeyler','/assets/katalog/iris-ceramica-avista.jpg'],
    ['Fiandre','General Fiandre Maximum','Seramik ve yüzeyler','/assets/katalog/fiandre-general-fiandre-maximum.jpg'],
    ['Fiandre','Maximum in Stone','Seramik ve yüzeyler','/assets/katalog/fiandre-maximum-in-stone.jpg'],
    ['Ceramica Cielo','Ceramic Design Book','Vitrifiye ve Banyo','/assets/katalog/ceramica-cielo-ceramic-design-book.jpg'],
    ['Ceramica Cielo','Le Acque di Cielo','Vitrifiye ve Banyo','/assets/katalog/ceramica-cielo-le-acque-di-cielo.jpg'],
    ['Ceramica Cielo','News 2026','Vitrifiye ve Banyo','/assets/katalog/ceramica-cielo-news-2026.webp'],
    ['Ceramica Cielo','News 2024','Vitrifiye ve Banyo','/assets/katalog/ceramica-cielo-news-2024.jpg'],
    ['Ceramica Cielo','I Catini','Vitrifiye ve Banyo','/assets/katalog/ceramica-cielo-i-catini.jpg'],
    ['Ceramica Cielo','Marcel','Vitrifiye ve Banyo','/assets/katalog/ceramica-cielo-marcel.jpg'],
    ['Ceramica Cielo','Theo','Vitrifiye ve Banyo','/assets/katalog/ceramica-cielo-theo.jpg'],
    ['Ceramica Cielo','Era','Vitrifiye ve Banyo','/assets/katalog/ceramica-cielo-era.jpg'],
    ['Ceramica Cielo','Mare','Vitrifiye ve Banyo','/assets/katalog/ceramica-cielo-mare.jpg'],
    ['Ceramica Cielo','Les Petites','Vitrifiye ve Banyo','/assets/katalog/ceramica-cielo-les-petites.jpg'],
    ['Ceramica Cielo','Infinito New','Vitrifiye ve Banyo','/assets/katalog/ceramica-cielo-infinito-new.jpg'],
    ['Ceramica Cielo','Plinio - Delfo - Multiplo','Vitrifiye ve Banyo','/assets/katalog/ceramica-cielo-plinio-delfo-multiplo.jpg'],
    ['Ceramica Cielo','General Book','Vitrifiye ve Banyo','/assets/katalog/ceramica-cielo-general-book.jpg'],
    ['CEA Design','Integrated Modular System','Bataryalar','/assets/katalog/cea-integrated-modular-system.jpg'],
    ['CEA Design','Cucina','Bataryalar','/assets/katalog/cea-cucina.jpg'],
    ['CEA Design','Collections Overview','Bataryalar','/assets/katalog/cea-design-collections-overview.jpg'],
    ['CEA Design','ALLURE','Bataryalar','/assets/katalog/cea-design-allure.jpg'],
    ['Emilgroup','General Catalogue 6.5 MM','Seramik ve yüzeyler','/assets/katalog/emilgroup-general-catalogue-6-5-mm.jpg'],
    ['Emilgroup','General Catalogue 20MM','Seramik ve yüzeyler','/assets/katalog/emilgroup-general-catalogue-20mm.jpg'],
    ['Emilceramica','Emilceramica General Catalogue 2026.05','Seramik ve yüzeyler','/assets/katalog/emilceramica-emilceramica-general-catalogue-2026-05.jpg'],
    ['Emilceramica','Tele di Marmo Catalogue 2026.09','Seramik ve yüzeyler','/assets/katalog/emilceramica-tele-di-marmo-catalogue-2026-09.jpg'],
    ['Ergon','Ergon General Catalogue 2026.05','Seramik ve yüzeyler','/assets/katalog/ergon-ergon-general-catalogue-2026-05.jpg'],
    ['Ergon','ConceptStone Preview Catalogue 2026.09','Seramik ve yüzeyler','/assets/katalog/ergon-conceptstone-preview-catalogue-2026-09.jpg'],
    ['Provenza','Provenza General Catalogue 2026.04','Seramik ve yüzeyler','/assets/katalog/provenza-provenza-general-catalogue-2026-04.jpg'],
    ['Provenza','Fornace Provenza Catalogue 2026.07','Seramik ve yüzeyler','/assets/katalog/provenza-fornace-provenza-catalogue-2026-07.jpg'],
    ['Viva','Viva General Catalogue 2026.04','Seramik ve yüzeyler','/assets/katalog/viva-viva-general-catalogue-2026-04.jpg'],
    ['Viva','Metallica Catalogue 2026.02','Seramik ve yüzeyler','/assets/katalog/viva-metallica-catalogue-2026-02.jpg'],
    ['Level','Level General Catalogue 2026.04','Seramik ve yüzeyler','/assets/katalog/level-level-general-catalogue-2026-04.jpg'],
    ['Level','Level General Catalogue Light 2026.04','Seramik ve yüzeyler','/assets/katalog/level-level-general-catalogue-light-2026-04.jpg']
  ].map(([brand,title,category,image]) => ({
    brand, title, category, image, url: sources[brand],
    slug: slugify(brand + ' ' + title)
  }));

  function escapeHTML(value) {
    return String(value).replace(/[&<>'"]/g, character => ({
      '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;'
    })[character]);
  }

  // Katalog kartlarinda buyuk, gomulu PNG verileri yerine web icin optimize
  // edilmis dosyalari kullan. Bu sayede kapaklar eksik/yari yuklenmez ve
  // tarayici bellek sinirlarina takilmaz.
  const catalogueFallbackCovers = {
    'basin-v2.png': '/assets/katalog/fallback/project-v2.webp',
    'vanity-v2.png': '/assets/katalog/fallback/showroom-v2.webp',
    'project-v2.png': '/assets/katalog/fallback/project-v2.webp',
    'home-hero-v2.png': '/assets/katalog/fallback/spa-v2.webp',
    'showroom-v2.png': '/assets/katalog/fallback/showroom-v2.webp',
    'spa-v2.png': '/assets/katalog/fallback/spa-v2.webp'
  };

  function imageURL(key) {
    try {
      const source = String(key || '');
      if (/^(https?:\/\/|\/assets\/katalog\/)/i.test(source)) return source;
      return catalogueFallbackCovers[source] || I[source] || I['showroom-v2.png'];
    }
    catch (_) { return ''; }
  }

  function card(item) {
    const brand = escapeHTML(item.brand);
    const title = escapeHTML(item.title);
    const category = escapeHTML(item.category);
    const url = escapeHTML(item.url);
    return `<article class="catalogue-card catalogue-card-expanded" data-catalogue-category="${category}">
      <a class="catalogue-cover catalogue-cover-clean" href="${url}" target="_blank" rel="noopener noreferrer" aria-label="${brand} ${title} kataloğunu yeni sekmede aç">
        <img src="${imageURL(item.image)}" data-cover-slug="${escapeHTML(item.slug)}" alt="${brand} ${title} katalog kapak görseli" loading="lazy">
      </a>
      <div class="catalogue-card-copy">
        <p>${brand}</p><h4>${title}</h4>
        <div><span>${category}</span><a href="${url}" target="_blank" rel="noopener noreferrer">Kataloğu İncele <span aria-hidden="true">›</span></a></div>
      </div>
    </article>`;
  }

  // /assets/katalog/<slug>.(jpg|webp|png|jpeg) varsa o kapağı kullan, yoksa mevcut görsel kalsın.
  function loadLocalCovers(root) {
    const extensions = ['jpg', 'webp', 'png', 'jpeg'];
    const apply = img => {
      const slug = img.dataset.coverSlug;
      if (!slug || img.dataset.coverChecked) return;
      img.dataset.coverChecked = 'true';
      (function tryNext(index) {
        if (index >= extensions.length) return;
        const url = '/assets/katalog/' + slug + '.' + extensions[index];
        const probe = new Image();
        probe.onload = () => { img.src = url; img.classList.add('has-brand-cover'); };
        probe.onerror = () => tryNext(index + 1);
        probe.src = url;
      })(0);
    };
    const images = root.querySelectorAll('img[data-cover-slug]');
    if ('IntersectionObserver' in window) {
      const observer = new IntersectionObserver(entries => entries.forEach(entry => {
        if (entry.isIntersecting) { observer.unobserve(entry.target); apply(entry.target); }
      }), { rootMargin: '600px 0px' });
      images.forEach(img => observer.observe(img));
    } else {
      images.forEach(apply);
    }
  }

  function rebuild() {
    if (!window.__likyaHash.startsWith('#/kataloglar')) return;
    const archive = document.querySelector('.catalogue-archive');
    const grid = archive && archive.querySelector('.catalogue-card-grid');
    const filters = archive && archive.querySelector('.catalogue-filters');
    if (!grid || !filters || grid.dataset.expanded === 'true') return;

    grid.dataset.expanded = 'true';
    grid.innerHTML = catalogues.map(card).join('');
    loadLocalCovers(grid);

    const categories = ['Tüm Kataloglar', ...new Set(catalogues.map(item => item.category))];
    filters.innerHTML = `<div class="catalogue-filter-heading"><span>Kategoriler</span><small>${catalogues.length}</small></div>` +
      categories.map((category, index) => {
        const count = category === 'Tüm Kataloglar' ? catalogues.length : catalogues.filter(item => item.category === category).length;
        return `<button type="button" data-catalogue-filter="${escapeHTML(category)}" class="${index === 0 ? 'selected' : ''}" aria-pressed="${index === 0 ? 'true' : 'false'}"><span>${escapeHTML(category)}</span><small>${count}</small></button>`;
      }).join('');

    const headingCount = archive.querySelector('[data-catalogue-count]');
    if (headingCount) headingCount.textContent = `${catalogues.length} katalog`;

    const buttons = [...filters.querySelectorAll('[data-catalogue-filter]')];
    const cards = [...grid.querySelectorAll('[data-catalogue-category]')];
    const title = archive.querySelector('[data-catalogue-title]');
    buttons.forEach(button => button.addEventListener('click', () => {
      const selected = button.dataset.catalogueFilter;
      let visible = 0;
      buttons.forEach(candidate => {
        const active = candidate === button;
        candidate.classList.toggle('selected', active);
        candidate.setAttribute('aria-pressed', active ? 'true' : 'false');
      });
      cards.forEach(item => {
        const show = selected === 'Tüm Kataloglar' || item.dataset.catalogueCategory === selected;
        item.hidden = !show;
        if (show) visible++;
      });
      if (title) title.textContent = selected;
      if (headingCount) headingCount.textContent = `${visible} katalog`;
    }));
  }

  document.addEventListener('DOMContentLoaded', rebuild);
  window.addEventListener('hashchange', () => setTimeout(rebuild, 0));
  new MutationObserver(rebuild).observe(document.documentElement, {childList:true, subtree:true});
  rebuild();
})();
</script>
