<script data-bundle="likya-profession-contractor-option">
/* Profesyonel proje talebi: meslek listesine tum ekranlarda Mutahhit secenegini ekle. */
(function () {
  function addContractorOption(root) {
    const scope = root && root.querySelectorAll ? root : document;
    scope.querySelectorAll('select[name="meslek"]').forEach(function (select) {
      if ([...select.options].some(function (option) { return option.value === 'Müteahhit'; })) return;
      const option = new Option('Müteahhit', 'Müteahhit');
      const installer = [...select.options].find(function (item) { return item.value === 'Yüklenici / Uygulamacı'; });
      select.insertBefore(option, installer || select.options[select.options.length - 1] || null);
    });
  }

  document.addEventListener('DOMContentLoaded', function () { addContractorOption(document); });
  window.addEventListener('hashchange', function () { setTimeout(function () { addContractorOption(document); }, 0); });
  new MutationObserver(function (records) {
    records.forEach(function (record) {
      record.addedNodes.forEach(function (node) {
        if (node.nodeType === 1) addContractorOption(node.matches('select[name="meslek"]') ? node.parentNode : node);
      });
    });
  }).observe(document.documentElement, { childList: true, subtree: true });
  addContractorOption(document);
})();
</script>
